/*
 * 中学数学・理科・社会の追加単元のテキスト本文(高校入試レベル)。このアプリのオリジナル。
 * m_proof・m_pattern・s_mag・s_env・c_jregion・c_jinken。書式は lessons_1.js 冒頭のコメントと同じ。
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ===== 中学数学:証明 =====
  L.m_proof = {
    goal: '仮定と結論を区別し、三角形の合同条件・二等辺三角形・平行四辺形の性質を根拠にして、筋の通った証明を書けるようになる。',
    intro: '証明は、裁判で「なぜそう言えるのか」を一つずつ証拠で示していく作業に似ています。「見ればわかる」「たぶんそう」は証拠になりません。【わかっていること(仮定)】から出発し、だれもが認める【根拠】だけを使って、【示したいこと(結論)】にたどりつく。この単元では、その書き方の型を身につけます。',
    pre: '【対頂角】は、2直線が交わってできる向かい合った角で、いつも等しくなります。\n2本の直線に別の直線が交わるとき、同じ位置にある角を【同位角】、内側で斜めに向かい合う角を【錯角】といいます。2直線が平行なら、同位角も錯角も等しくなります。逆に、同位角か錯角が等しければ、2直線は平行です。\n三角形の内角の和は 180° です。また、三角形の1つの外角は、それと隣り合わない2つの内角の和に等しくなります。\n【合同】とは、形も大きさも同じで、ぴったり重なることです。記号 ≡ を使い、△ABC≡△DEF のように書きます。このとき、重なり合う頂点(対応する頂点)を同じ順に書くのがきまりです。\n合同な図形では、対応する辺の長さも、対応する角の大きさもそれぞれ等しくなります。証明では、この性質を使って「辺が等しい」「角が等しい」を導きます。',
    secs: [
      { h: '証明とは何か:仮定と結論', t: 'なぜ証明が必要なのでしょうか。図をかいて測ると等しく見えても、それは「その図ではたまたまそうだった」だけかもしれません。どんな形の図でも必ず成り立つことを示すには、ことばと根拠で説明するしかありません。これが【証明】です。\n「○○ならば△△」という形の文で、「ならば」の前の部分を【仮定】、後の部分を【結論】といいます。仮定は「はじめからわかっていること」、結論は「これから示したいこと」です。\n証明を書く前に、まず仮定と結論をはっきり書き出します。問題文に「〜のとき」「〜とする」とあれば、それが仮定です。「〜であることを証明しなさい」の部分が結論です。\n証明で使ってよい根拠は、仮定のほかに、【定義】(ことばの意味を決めたもの。例:二等辺三角形とは2辺が等しい三角形)と、すでに正しいと証明された【定理】(例:対頂角は等しい)です。',
        key: '「ならば」の前が仮定、後が結論。使ってよい根拠は、仮定・定義・すでに証明された定理だけ。',
        ex: [{ q: '「△ABC で、AB＝AC ならば ∠B＝∠C である」の仮定と結論を答えなさい。', hint: '「ならば」の前後に分けます。', steps: ['文を「ならば」で前と後に分ける。', '前の「AB＝AC」が、はじめからわかっていること(仮定)。', '後の「∠B＝∠C」が、示したいこと(結論)。'], a: '仮定:AB＝AC  結論:∠B＝∠C', check: '仮定と結論を入れかえた文(∠B＝∠C ならば AB＝AC)は「逆」とよばれる別の文になることも、合わせて確かめておきましょう。' }] },
      { h: '三角形の合同条件', t: '2つの三角形が合同であることを示すのに、6つ(3辺と3角)すべてが等しいと確かめる必要はありません。次の3つのうちどれか1つが言えれば合同です。これを【三角形の合同条件】といいます。\n①【3組の辺】がそれぞれ等しい。\n②【2組の辺とその間の角】がそれぞれ等しい。\n③【1組の辺とその両端の角】がそれぞれ等しい。\nなぜこれで十分かというと、どの条件でも三角形の形が1通りに決まってしまうからです。たとえば②なら、2本の辺の長さと開き具合を決めると、残りの辺は自動的に決まります。\n注意したいのは「間の角」「両端の角」という位置の指定です。2組の辺と、その間にない角が等しくても、合同になるとは限りません。また、3つの角が等しいだけでは、大きさがちがう三角形(拡大図・縮図)がありえるので合同にはなりません。\n③を使うとき、「1組の辺と2つの角」がわかれば、三角形の内角の和が 180° であることから3つ目の角も決まるので、両端の角をそろえることができます。',
        key: '合同条件は「3辺」「2辺とその間の角」「1辺とその両端の角」の3つ。角の位置まで正確に。' },
      { h: '証明の書き方の型', t: '証明はいつも同じ型で書くと、まちがいが減ります。\n①【どの三角形を比べるか】を書く:「△AOC と △BOD において」。\n②【等しいものを根拠つきで並べる】:「仮定より AO＝BO …①」「対頂角は等しいから ∠AOC＝∠BOD …②」のように、1行に1つ、理由をつけて書きます。番号をつけておくと後で使いやすくなります。\n③【合同条件を書く】:「①、②、③より、2組の辺とその間の角がそれぞれ等しいから」。\n④【合同を書く】:「△AOC≡△BOD」。対応する頂点の順番をそろえます。\n⑤【結論を書く】:「合同な図形の対応する辺は等しいから AC＝BD」。\nなぜ根拠を毎行書くのかというと、読む人が「本当にそう言えるのか」を1行ずつ確かめられるようにするためです。根拠のない「＝」が1つでもあると、その証明は成り立ちません。',
        key: '「比べる三角形 → 等しいもの3つ(根拠つき) → 合同条件 → 合同 → 結論」の型で書く。',
        ex: [{ q: '線分 AB と線分 CD が、それぞれの中点 O で交わっている。このとき AC＝BD であることを証明しなさい。', hint: 'AC と BD をふくむ三角形を見つけ、その2つが合同であることを示します。', steps: ['結論の AC と BD をふくむ三角形として、△AOC と △BOD を比べると決める。', 'O は AB の中点だから AO＝BO …①、O は CD の中点だから CO＝DO …②。', '対頂角は等しいから ∠AOC＝∠BOD …③。③の角は、①・②の辺の間の角になっている。', '①、②、③より、2組の辺とその間の角がそれぞれ等しいから △AOC≡△BOD。', '合同な図形の対応する辺は等しいから AC＝BD。'], a: '△AOC と △BOD において、仮定より AO＝BO …①、CO＝DO …②。対頂角は等しいから ∠AOC＝∠BOD …③。①、②、③より、2組の辺とその間の角がそれぞれ等しいから △AOC≡△BOD。合同な図形の対応する辺は等しいので AC＝BD。', check: '△AOC≡△BOD で、A と B、O と O、C と D が対応しているか(同じ順に書いたか)を確かめます。AC と BD はたしかに対応する辺です。' }] },
      { h: '二等辺三角形の定義と定理', t: '【二等辺三角形】の定義は「2つの辺が等しい三角形」です。等しい2辺の間の角を【頂角】、残りの2つの角を【底角】、頂角に向かい合う辺を【底辺】といいます。\n二等辺三角形には、次の【定理】があります。\n・二等辺三角形の【2つの底角は等しい】。\n・二等辺三角形の【頂角の二等分線は、底辺を垂直に2等分する】。\n底角が等しいことは、頂角の二等分線を引いてできる2つの三角形が合同であることから証明できます(下の例題)。一度証明された定理は、次からは根拠として使えます。\nまた、逆の「2つの角が等しい三角形は、二等辺三角形である」も正しいことが証明されています。角が等しいことから辺が等しいことを示したいときに使います。\n正三角形は「3辺が等しい三角形」で、二等辺三角形の特別な場合です。3つの角はすべて 60° になります。',
        key: '定義「2辺が等しい」、定理「底角は等しい」「頂角の二等分線は底辺を垂直に2等分」。逆「2角が等しければ二等辺三角形」。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="二等辺三角形ABCと頂角の二等分線AD。AB＝AC、∠BAD＝∠CAD"><path d="M110 18 L45 122 L175 122 Z" class="tr"/><line x1="110" y1="18" x2="110" y2="122" class="dash"/><line x1="72" y1="66" x2="80" y2="72" class="cv2"/><line x1="140" y1="72" x2="148" y2="66" class="cv2"/><path d="M104 32 Q107 36 110 34" class="arc"/><path d="M110 34 Q113 36 116 32" class="arc"/><rect x="110" y="114" width="8" height="8" class="rt"/><text x="104" y="13">A</text><text x="32" y="134">B</text><text x="178" y="134">C</text><text x="106" y="138">D</text><text x="10" y="64">AB＝AC</text><text x="128" y="96">AD は ∠A の</text><text x="128" y="108">二等分線</text></svg>',
        ex: [{ q: 'AB＝AC の二等辺三角形 ABC で、∠A の二等分線と辺 BC の交点を D とする。∠B＝∠C であることを証明しなさい。', hint: '△ABD と △ACD を比べます。共通な辺 AD も根拠になります。', steps: ['△ABD と △ACD において、と比べる三角形を書く。', '仮定より AB＝AC …①。', 'AD は ∠A の二等分線だから ∠BAD＝∠CAD …②。', 'AD は共通だから AD＝AD …③。', '①、②、③より、2組の辺とその間の角がそれぞれ等しいから △ABD≡△ACD。対応する角は等しいので ∠B＝∠C。'], a: '△ABD と △ACD において、仮定より AB＝AC …①、∠BAD＝∠CAD …②、共通な辺だから AD＝AD …③。①〜③より2組の辺とその間の角がそれぞれ等しいから △ABD≡△ACD。よって ∠ABD＝∠ACD、すなわち ∠B＝∠C。', check: '②の角が、①の辺 AB・AC と③の辺 AD の「間の角」になっているかを図で確かめます。' },
          { q: 'AB＝AC の二等辺三角形 ABC で、∠A＝50° のとき、∠B の大きさを求めなさい。また、辺 BC を C の方へのばした直線上に点 E をとるとき、∠ACE を求めなさい。', hint: '底角は等しい。外角は隣り合わない2つの内角の和です。', steps: ['二等辺三角形の底角は等しいので ∠B＝∠C。', '内角の和より ∠B＋∠C＝180°−50°＝130°。', '∠B＝130°÷2＝65°。', '∠ACE は ∠C の外角なので、∠A＋∠B＝50°＋65°＝115°。'], a: '∠B＝65°、∠ACE＝115°', check: '∠ACE＋∠C＝115°＋65°＝180° で、一直線になっていることを確かめます。' }] },
      { h: '直角三角形の合同条件', t: '直角三角形では、直角に向かい合う辺を【斜辺】といいます。直角三角形どうしは、ふつうの3つの合同条件のほかに、次の2つでも合同だといえます。\n①【斜辺と1つの鋭角】がそれぞれ等しい。\n②【斜辺と他の1辺】がそれぞれ等しい。\nなぜこれで言えるのでしょうか。①は、直角と1つの鋭角が等しければ、内角の和から残りの角も等しくなるので、「1組の辺(斜辺)とその両端の角」が等しいことになるからです。②は、2つの直角三角形を等しい辺どうしでつなぐと二等辺三角形ができ、底角が等しいことから示せます。\nこの条件を使う前に、必ず「∠C＝∠F＝90°」のように、どちらも直角三角形であることを書きます。これを書き忘れると、直角三角形の合同条件は使えません。\nよく出るのは、角の二等分線上の点から2辺にひいた垂線の長さが等しいことを示す問題や、二等辺三角形の頂点から垂線をひく問題です。',
        key: '直角三角形の合同条件は「斜辺と1つの鋭角」「斜辺と他の1辺」。使う前に「どちらも直角」を必ず書く。' },
      { h: '平行四辺形の性質と、平行四辺形になる条件', t: '【平行四辺形】の定義は「2組の向かい合う辺(対辺)がそれぞれ平行な四角形」です。\n平行四辺形には次の【性質】があります。①2組の対辺はそれぞれ等しい。②2組の向かい合う角(対角)はそれぞれ等しい。③対角線はそれぞれの中点で交わる。これらは、対角線をひいてできる2つの三角形の合同から証明できます。\n反対に、ある四角形が平行四辺形であることを示すには、次の【平行四辺形になるための条件】のどれか1つを示します。①2組の対辺がそれぞれ平行(定義)。②2組の対辺がそれぞれ等しい。③2組の対角がそれぞれ等しい。④対角線がそれぞれの中点で交わる。⑤1組の対辺が平行で、その長さが等しい。\n⑤は「同じ1組」が平行かつ等しいことが大切です。「1組は平行、別の1組は等しい」では、等脚台形の場合があるので平行四辺形とは限りません。\n特別な平行四辺形も整理しておきましょう。【長方形】は4つの角が等しく、対角線の長さが等しい。【ひし形】は4つの辺が等しく、対角線が垂直に交わる。【正方形】は長方形とひし形の両方の性質をもちます。',
        key: '平行四辺形になる条件は5つ。⑤「1組の対辺が平行で長さが等しい」は同じ1組で言う。',
        ex: [{ q: '平行四辺形 ABCD の対角線 BD 上に、BE＝DF となる点 E、F をとる(E は B に近い側)。四角形 AECF が平行四辺形であることを証明しなさい。', hint: '対角線 AC と BD の交点を O とし、「対角線がそれぞれの中点で交わる」条件を使います。', steps: ['対角線 AC と BD の交点を O とする。', '平行四辺形の対角線はそれぞれの中点で交わるから AO＝CO …①、BO＝DO …②。', '仮定より BE＝DF …③。②、③より EO＝BO−BE、FO＝DO−DF だから EO＝FO …④。', '四角形 AECF の対角線は AC と EF で、①、④よりそれぞれの中点 O で交わっている。', '対角線がそれぞれの中点で交わるので、四角形 AECF は平行四辺形である。'], a: '対角線の交点を O とすると、平行四辺形の性質より AO＝CO、BO＝DO。BE＝DF だから EO＝BO−BE＝DO−DF＝FO。四角形 AECF の対角線 AC、EF はそれぞれの中点 O で交わるから、四角形 AECF は平行四辺形である。', check: '使った条件が「平行四辺形になるための条件」の5つのうちの④であることを確かめます。性質(ABCD がもつもの)と条件(AECF に示すもの)を混同していないかも点検します。' }] },
      { h: '逆と反例', t: 'ある文の仮定と結論を入れかえた文を、もとの文の【逆】といいます。「a＝b ならば a²＝b²」の逆は「a²＝b² ならば a＝b」です。\nもとの文が正しくても、逆が正しいとは限りません。上の例では a＝2、b＝−2 のとき a²＝b² ですが a≠b です。このように、文が成り立たないことを示す例を【反例】といいます。\n正しくないことを示すには、反例を1つ挙げれば十分です。反対に、正しいことを示すには、すべての場合について成り立つ証明が必要です。\n図形でも逆はよく出ます。「二等辺三角形の底角は等しい」の逆「2つの角が等しい三角形は二等辺三角形」は正しい例、「平行四辺形の対角線はそれぞれの中点で交わる」の逆「対角線がそれぞれの中点で交わる四角形は平行四辺形」も正しい例です。一方、「正方形ならば4つの辺が等しい」の逆「4つの辺が等しい四角形は正方形」は、ひし形が反例になるので正しくありません。',
        key: '逆は仮定と結論を入れかえた文。正しくないことは反例1つで示せる。',
        ex: [{ q: '「2つの自然数 a、b がともに偶数ならば、a＋b は偶数である」の逆を書き、それが正しいかどうかを答えなさい。正しくない場合は反例を挙げなさい。', hint: '仮定と結論を入れかえます。和が偶数になる奇数どうしを考えてみましょう。', steps: ['仮定「a、b がともに偶数」と結論「a＋b は偶数」を入れかえる。', '逆は「a＋b が偶数ならば、a、b はともに偶数である」。', '和が偶数になる例を探すと、a＝1、b＝3 のとき a＋b＝4 は偶数だが、a、b はどちらも奇数。', 'これが反例になるので、逆は正しくない。'], a: '逆:「a＋b が偶数ならば、a、b はともに偶数である」。正しくない。反例:a＝1、b＝3(和は4で偶数だが、どちらも奇数)。', check: '反例が「逆の仮定(a＋b が偶数)を満たし、結論(ともに偶数)を満たさない」ものになっているかを確かめます。' }] },
      { h: 'もっと深く:合同条件はなぜこの3つなのか', t: '三角形の合同条件は「3組の辺」「2組の辺とその間の角」「1組の辺とその両端の角」の3つでした。では、なぜこの3つで十分で、ほかの組み合わせではだめなのでしょうか。\nカギになるのは、【三角形が1つに決まる条件】(三角形の決定条件)です。3辺の長さが決まれば、コンパスで作図すると三角形の形と大きさは1通りに決まります。2辺とその間の角、1辺とその両端の角の場合も同じです。形と大きさが1通りに決まるなら、その条件が同じ2つの三角形は必ずぴったり重なる、つまり合同です。\n反対に、【2辺とその間にない角】では、三角形が1つに決まらないことがあります。たとえば、∠B＝30°、AB＝10 cm、AC＝6 cm の三角形を作図すると、点 C は B から引いた半直線上の2か所にとれてしまいます(A を中心に半径 6 cm の円をかくと、半直線と2点で交わるため)。同じ条件なのに形のちがう三角形が2つできるので、これは合同条件になりません。証明で「2辺と1角」を使うときに、角が【間の角】かどうかを必ず確かめるのはこのためです。\n「3つの角がそれぞれ等しい」も合同条件ではありません。形は同じでも、大きさがちがう三角形がいくらでもつくれるからです。この「形が同じ」という関係は、中学3年で学ぶ【相似】につながります。\n直角三角形の合同条件も、ふつうの合同条件から導けます。「斜辺と1つの鋭角」が等しければ、三角形の内角の和が180°なので残りの角も等しくなり、「1組の辺とその両端の角」が等しいことになります。「斜辺と他の1辺」の場合は、2つの三角形を等しい辺どうしで合わせて裏返しに並べると二等辺三角形ができ、その底角が等しいことから「斜辺と1つの鋭角」に帰着できます。',
        key: '合同条件=三角形が1つに決まる条件。「2辺とその間にない角」は三角形が2通りできることがあるので合同条件ではない。3つの角が等しいだけでは相似。' },
      { h: '入試ではこう出る:証明と、その結果を使う問題', t: '高校入試の図形の証明は、①根拠や合同条件を空らんに入れる【穴うめ型】、②証明をすべて書く【記述型】、③証明したことを使って長さや角を求める【活用型】の形で出ます。中学3年の相似や円周角と組み合わせた問題も多いですが、骨組みは合同の証明と同じです。\n①の穴うめ型では、空らんの前後を読んで「どの三角形の、どの辺(角)の話か」を確かめます。「対頂角」「錯角」「同位角」「共通な辺」などの根拠のことばと、合同条件の正確な言い方(「2組の辺とその間の角がそれぞれ等しい」など)をすらすら書けるようにしておきましょう。\n②の記述型で部分点を落としやすいのは、【根拠を書かない】、【合同条件の名前がずれている】(使った条件と書いた条件がちがう)、【対応する頂点の順番がそろっていない】の3つです。△ABC≡△DEF と書くときは、A と D、B と E、C と F が対応するように並べます。\n③の活用型では、合同から分かる「対応する辺や角が等しい」ことを使って、次の問いに進みます。たとえば、合同から角が等しいことを示し、三角形の内角の和を使って垂直であることを導く、といった流れです。\n時間配分では、証明は書く量が多いので、まず図に仮定の印(等しい辺・角)をかきこみ、結論から逆にたどって方針を決めてから書き始めると、書き直しが減ります。',
        key: '部分点を落とす3大ミス=根拠なし・合同条件のずれ・頂点の対応の順番。合同で分かった等しい角を、次の問い(垂直など)に使う。',
        ex: [
          { q: '正方形 ABCD の辺 BC 上に点 E、辺 CD 上に点 F を、BE＝CF となるようにとる。\n(1) AE＝BF であることを証明しなさい。\n(2) AE と BF の交点を G とするとき、∠BGE の大きさを求めなさい。', hint: '(1) は △ABE と △BCF を比べます。(2) は (1) で分かる等しい角と、直角三角形の角の関係を使います。', steps: ['(1) △ABE と △BCF において、正方形の辺だから AB＝BC …①、正方形の角だから ∠ABE＝∠BCF＝90° …②、仮定より BE＝CF …③。', '①〜③より、2組の辺とその間の角がそれぞれ等しいので △ABE≡△BCF。合同な図形の対応する辺は等しいから AE＝BF。', '(2) 合同な図形の対応する角は等しいから ∠BAE＝∠CBF …④。', '△ABE で ∠ABE＝90° なので ∠BAE＋∠AEB＝90°。④より ∠CBF＋∠AEB＝90°。', '△GBE で ∠GBE＝∠CBF、∠GEB＝∠AEB だから、∠BGE＝180°−(∠GBE＋∠GEB)＝180°−90°＝90°。'], a: '(1) △ABE と △BCF において、AB＝BC(正方形の辺)、∠ABE＝∠BCF＝90°(正方形の角)、BE＝CF(仮定)。2組の辺とその間の角がそれぞれ等しいから △ABE≡△BCF。よって AE＝BF。\n(2) 90°(AE と BF は垂直に交わる)', check: '(1) で頂点の対応が A↔B、B↔C、E↔F になっているか確かめます。(2) は図をかいて、E と F を辺の中点にしたときも直角に見えるかで確かめられます。' },
          { q: '線分 AD と線分 BC が点 M で交わっている。AB∥CD、AM＝DM のとき、BM＝CM であることを証明する。次の【 ア 】〜【 エ 】に当てはまることばや式を答えなさい。\n△ABM と △DCM において、仮定より AM＝DM …①\n【 ア 】は等しいから、AB∥CD より ∠BAM＝∠CDM …②\n【 イ 】は等しいから ∠AMB＝∠DMC …③\n①、②、③より、【 ウ 】がそれぞれ等しいから △ABM≡△DCM\n合同な図形の対応する辺は等しいから【 エ 】', hint: '②は平行線の性質、③は2直線が交わってできる角です。①の辺が、②・③の角の「間」にあるかを確かめます。', steps: ['②は AB∥CD のとき、直線 AD に対してできる ∠BAM と ∠CDM の関係なので「平行線の錯角」。', '③の ∠AMB と ∠DMC は、2直線 AD、BC が交わってできる向かい合った角なので「対頂角」。', '辺 AM の両端の角が ∠BAM(A の角)と ∠AMB(M の角)、辺 DM の両端の角が ∠CDM と ∠DMC なので、合同条件は「1組の辺とその両端の角」。', '結論は BM＝CM。'], a: 'ア 平行線の錯角 イ 対頂角 ウ 1組の辺とその両端の角 エ BM＝CM', check: '①の辺が②・③の角にはさまれているかを図で確かめます。はさまれていなければ「両端の角」とは言えません。' }
        ] }
    ],
    faq: [
      ['証明の文は、教科書とまったく同じでないとだめ?', '同じである必要はありません。大切なのは、比べる三角形・等しいもの3つとその根拠・合同条件・結論が、正しい順序でそろっていることです。\n「仮定より」「対頂角は等しいから」「共通な辺だから」などの根拠のことばは、入試の採点でも必ず見られるので省かないようにしましょう。'],
      ['どの三角形を比べればよいか分からないときは?', '結論から逆にたどります。示したいのが「AC＝BD」なら、AC と BD をそれぞれふくむ三角形を探します。\n次に、図に仮定の印(同じ長さに線の印、同じ角に弧の印)をかきこみ、共通な辺や対頂角、平行線の錯角など「仮定に書いていないけれど等しいもの」を探すと、3つ目が見つかりやすくなります。'],
      ['「性質」と「条件」は何がちがうの?', '「平行四辺形の性質」は、平行四辺形だとわかっている図形がもっている特徴です。「平行四辺形になるための条件」は、ある四角形を平行四辺形だと示すために確かめることです。\n証明の中では、すでに平行四辺形だとわかっている図形には性質を、これから平行四辺形だと示したい図形には条件を使います。'],
      ['仮定に書いていないのに「等しい」と使ってよいものには、ほかに何がある?', '対頂角・平行線の錯角や同位角・共通な辺のほかに、正方形や正三角形などの図形の【定義や性質】(辺がすべて等しい、角がすべて等しいなど)、二等辺三角形の底角、すでに証明した合同から分かる辺や角があります。\nまた、等しい長さから同じ長さをひいた残り(EO＝BO−BE＝DO−DF＝FO のような形)や、等しい角に同じ角をたした角も等しいといえます。どれも根拠のことばを書いてから使いましょう。']
    ],
    drill: [
      { lv: 1, q: '「x が4の倍数ならば、x は偶数である」の仮定と結論を答えなさい。', a: '仮定:x が4の倍数 結論:x は偶数である', exp: '「〜ならば」の前が仮定、後ろが結論です。\nこの文は正しい文です(4の倍数は 4n＝2×2n と表せるので偶数)。ただし、逆の「x が偶数ならば、x は4の倍数」は、x＝2 が反例になるので正しくありません。' },
      { lv: 1, q: '△ABC と △DEF で、AB＝DE、BC＝EF、∠B＝∠E のとき、使える合同条件を答えなさい。', a: '2組の辺とその間の角がそれぞれ等しい', exp: '∠B は辺 AB と辺 BC にはさまれた角、∠E は辺 DE と辺 EF にはさまれた角です。等しい2組の辺の「間の角」が等しいので、「2組の辺とその間の角」の条件にあたります。\n角が間にあるかどうかは、角の頂点の文字が2つの辺の両方にふくまれているかで確かめられます。' },
      { lv: 1, q: 'AB＝AC の二等辺三角形 ABC で、∠A＝40° のとき、∠B の大きさを求めなさい。', a: '70°', exp: '二等辺三角形の底角は等しいので、∠B＝∠C です。内角の和は180°なので、∠B＝(180°−40°)÷2＝70° です。\n頂角(等しい2辺にはさまれた角)がどれかを、まず確かめてから計算しましょう。' },
      { lv: 2, q: '「x＝3 ならば x²＝9 である」の逆を書き、正しいかどうかを答えなさい。正しくない場合は反例を挙げなさい。', a: '逆:「x²＝9 ならば x＝3 である」。正しくない。反例:x＝−3', exp: '仮定と結論を入れかえると逆になります。x²＝9 を満たす x は 3 と −3 の2つあるので、x＝−3 のとき仮定(x²＝9)は成り立つのに結論(x＝3)は成り立ちません。\nこのように、正しい文の逆が正しいとは限りません。反例は、逆の仮定を満たし、結論を満たさない例を1つ挙げます。' },
      { lv: 2, q: '平行四辺形 ABCD で、∠A＝110° のとき、∠B と ∠C の大きさを求めなさい。', a: '∠B＝70°、∠C＝110°', exp: '平行四辺形の対角は等しいので、∠C＝∠A＝110° です。\n四角形の内角の和は360°で、∠B＝∠D でもあるので、∠B＝(360°−110°×2)÷2＝70° です。となり合う角の和が180°(∠A＋∠B＝180°)になることも、平行四辺形の大事な性質です。4つの角の和が 110°＋70°＋110°＋70°＝360° になることで確かめられます。' },
      { lv: 2, q: 'AB＝AC の二等辺三角形 ABC で、∠B＝72° のとき、∠A の大きさを求めなさい。', a: '36°', exp: '二等辺三角形の底角は等しいので、∠C＝∠B＝72° です。\n内角の和は180°なので、∠A＝180°−72°×2＝36° です。底角と頂角を取りちがえて (180°−72°)÷2＝54° としないように注意しましょう。' },
      { lv: 3, q: 'AB＝AC の二等辺三角形 ABC で、辺 AB 上に点 D、辺 AC 上に点 E を、AD＝AE となるようにとる。BE＝CD であることを証明しなさい。', a: '△ABE と △ACD において、仮定より AB＝AC …①、AE＝AD …②、共通な角だから ∠BAE＝∠CAD …③。①、②、③より、2組の辺とその間の角がそれぞれ等しいから △ABE≡△ACD。合同な図形の対応する辺は等しいから BE＝CD。', exp: '結論の BE と CD をふくむ三角形を探すと、△ABE と △ACD が見つかります。この2つは頂点 A の角を共有しています。\n等しいものは、仮定の AB＝AC、AE＝AD と、共通な角 ∠A です。∠A は AB と AE、AC と AD の間の角なので、「2組の辺とその間の角」が使えます。\n採点のポイントは、①比べる三角形を明示しているか、②3つの等しいものにそれぞれ根拠があるか、③合同条件が正しいか、④頂点の対応(B↔C、E↔D)がそろっているか、です。' },
      { lv: 3, q: '平行四辺形 ABCD の辺 AD の中点を M、辺 BC の中点を N とする。四角形 MBND が平行四辺形であることを証明しなさい。', a: '平行四辺形の対辺は平行だから AD∥BC、よって MD∥BN …①。平行四辺形の対辺は等しいから AD＝BC。M、N はそれぞれ AD、BC の中点だから MD＝AD/2、BN＝BC/2 より MD＝BN …②。①、②より、1組の対辺が平行でその長さが等しいから、四角形 MBND は平行四辺形である。', exp: '四角形 MBND の辺のうち、MD と BN は、もとの平行四辺形の辺 AD と BC の一部です。だから、平行であることと、長さが等しいことの両方が言えます。\nこのとき使う条件は「1組の対辺が平行で、その長さが等しい」です。平行と長さが等しいのが【同じ1組】(MD と BN)であることが大切です。\n採点のポイントは、ABCD の性質(平行・等しい)と、MBND に示す条件を区別して書いているかです。' }
    ],
    terms: [['仮定', '「○○ならば△△」の「○○」の部分。はじめからわかっていること'], ['結論', '「○○ならば△△」の「△△」の部分。証明して示したいこと'], ['定義', 'ことばの意味をはっきり決めたもの(例:二等辺三角形は2辺が等しい三角形)'], ['定理', '証明された正しいことがらのうち、よく使われる大切なもの'], ['合同', '形も大きさも同じで、ぴったり重なること。記号 ≡'], ['斜辺', '直角三角形で、直角に向かい合う辺'], ['逆', 'ある文の仮定と結論を入れかえた文'], ['反例', 'ある文が成り立たないことを示す例']],
    miss: ['合同の記号 ≡ の両側で、対応する頂点の順番をそろえない。順番がずれると、対応する辺や角をまちがえてしまいます。図で重なる頂点を確かめてから書きましょう。', '「2組の辺と1つの角」が等しいだけで合同としてしまう。角が「その間の角」でないと合同とは限りません。角が2辺にはさまれているかを図で指で確かめましょう。', '結論を根拠に使ってしまう(示したい ∠B＝∠C を途中で使うなど)。まだ証明していないことは根拠にできません。最初に結論を書き出し、それを使っていないか最後に点検しましょう。', '直角三角形の合同条件を使うのに、「∠C＝∠F＝90°」を書き忘れる。この条件は直角三角形どうしのときだけ使えるので、必ず最初に書きます。', '平行四辺形の条件⑤を「1組の対辺が平行、もう1組が等しい」とまちがえる。等脚台形が反例になります。「同じ1組が平行で長さも等しい」と覚えましょう。'],
    sum: ['証明は、仮定から根拠をつないで結論を示す文章。使える根拠は仮定・定義・定理。', '三角形の合同条件は「3辺」「2辺とその間の角」「1辺とその両端の角」。', '書き方の型は「比べる三角形 → 等しいもの(根拠つき) → 合同条件 → 合同 → 結論」。', '二等辺三角形の底角は等しい。直角三角形には「斜辺と1鋭角」「斜辺と他の1辺」の合同条件がある。', '平行四辺形の性質と、平行四辺形になるための5つの条件を区別して使う。', '逆はいつも正しいとは限らない。正しくないことは反例1つで示せる。'],
    next: '次は「三平方の定理・相似」(m_m11)で、相似の証明に進みましょう。合同の証明と同じ型で、相似条件(2組の角がそれぞれ等しい など)を使って書けます。円周角の定理を使う証明も、入試ではよく出ます。'
  };

  // ===== 中学数学:規則性 =====
  L.m_pattern = {
    goal: '数の並びや図形の個数の規則を見つけて、n 番目を文字式で表し、その式を使って「○番目はいくつか」「いくつになるのは何番目か」を求められるようになる。',
    intro: '階段を1段ずつ数えて100段目の高さを求めるのは大変ですが、「1段で20 cm 上がる」とわかれば、かけ算1回で求められます。規則性の問題も同じです。最初の何個かを調べて【きまり】を見つけ、それを【文字式】にすれば、どんなに先の番号でもすぐに計算できます。高校入試では、図形を並べる問題やカレンダー・表の問題として毎年のように出題されます。',
    pre: '【文字式】は、数の代わりに文字を使って表した式です。n 番目のように、番号を表すときは文字 n をよく使います。n は 1、2、3、… と変わる自然数です。\n文字式に数を入れることを【代入】といいます。4n−1 に n＝5 を代入すると 4×5−1＝19 です。\n【一次方程式】は、4n−1＝79 のような式から n を求めるものです。両辺に1をたして 4n＝80、両辺を4でわって n＝20 となります。\n【偶数】は 2n、【奇数】は 2n−1(または 2n＋1)と表せます。連続する整数は n、n＋1、n＋2 と表せます。\nn² は n×n のことです。1²＝1、2²＝4、3²＝9、4²＝16、5²＝25 は、すぐに言えるようにしておきましょう。',
    secs: [
      { h: 'まず表をつくり、増え方を調べる', t: 'なぜ表をつくるのでしょうか。規則は、頭の中で考えるよりも、数を並べて見比べたほうがずっと見つけやすいからです。\n表の上の段に番号(1番目、2番目、…)、下の段にその数や個数を書きます。最低でも4番目くらいまで調べます。図形の問題なら、実際に図をかいて数えます。\n次に、となりどうしの【差】を調べます。3, 7, 11, 15 なら差はいつも 4 です。差がいつも同じなら、「同じ数ずつ増える並び」です。\n差が同じでなければ、ほかのきまりを疑います。前の数を何倍かしていないか(2, 4, 8, 16 は2倍ずつ)、番号の2乗になっていないか(1, 4, 9, 16)、同じものがくり返していないか、などです。\n差がさらに規則的に増えていく(1, 3, 6, 10 の差は 2, 3, 4)という並びもあります。差の差を調べるのも、よく使う方法です。',
        key: '1〜4番目くらいまで表にして、となりどうしの差を調べる。差が一定なら「同じ数ずつ増える並び」。',
        ex: [{ q: '次の数の並びのきまりを見つけ、□にあてはまる数を答えなさい。\n(1) 5, 8, 11, 14, □  (2) 3, 6, 12, 24, □  (3) 2, 5, 10, 17, □', hint: 'まず差を調べ、差が一定でなければ倍やほかのきまりを考えます。', steps: ['(1) 差は 3, 3, 3 で一定なので、14＋3＝17。', '(2) 差は 3, 6, 12 で一定ではない。前の数を2倍しているので 24×2＝48。', '(3) 差は 3, 5, 7 と2ずつ増えている。次の差は9なので 17＋9＝26。', '(3) は「番号の2乗＋1」(1²＋1, 2²＋1, …)とも見られ、5²＋1＝26 で一致する。'], a: '(1) 17  (2) 48  (3) 26', check: '(3) を2つの方法で求めて、どちらも 26 になることで確かめられます。' }] },
      { h: '同じ数ずつ増える並びの n 番目', t: '最初の数が a で、d ずつ増える並びを考えます。2番目は a に d を1回、3番目は d を2回、…、n 番目は d を (n−1) 回たした数です。\nだから n 番目＝【a＋d×(n−1)】です。これを整理すると、d×n＋(a−d) の形になります。\n例:3, 7, 11, 15, … は a＝3、d＝4 なので、n 番目＝3＋4(n−1)＝4n−1 です。\n「なぜ n−1 なのか」がよくまちがえるところです。1番目は最初の数そのもので、まだ1回も増えていません。だから増えた回数は、番号より1少ないのです。植木算(木と木の間の数は、木の数より1少ない)と同じ考え方です。\n式ができたら、必ず n＝1、2 を代入して、もとの並びと一致するか確かめます。4n−1 なら n＝1 で 3、n＝2 で 7 となり、合っています。',
        key: 'n 番目＝最初の数＋増える数×(n−1)。できた式に n＝1、2 を入れて確かめる。',
        ex: [{ q: '7, 12, 17, 22, … と並ぶとき、(1) n 番目の数を n を使った式で表しなさい。(2) 30番目の数を求めなさい。(3) 217 は何番目の数ですか。', hint: '最初の数と、増える数を読み取ります。(3) は方程式を立てます。', steps: ['最初の数は 7、差は 5 なので n 番目＝7＋5(n−1)＝5n＋2。', 'n＝1 で 7、n＝2 で 12 となり、もとの並びと一致する。', '(2) n＝30 を代入して 5×30＋2＝152。', '(3) 5n＋2＝217 とおくと 5n＝215、n＝43。', 'n が自然数になったので、217 は並びの中にある数だとわかる。'], a: '(1) 5n＋2  (2) 152  (3) 43番目', check: '(3) で n が自然数にならなかったら、その数は並びに出てこないということです。ここでは 43 という自然数になったので適しています。' }] },
      { h: '図形の個数:マッチ棒と碁石', t: '図形を並べる問題では、「何がいくつずつ増えるか」を図の上で確かめることが大切です。\n例:マッチ棒で正方形を横1列につなげていきます。正方形1個に4本、2個に7本、3個に10本、…と、1個増えるごとに【3本】ずつ増えます。なぜ4本ではなく3本かというと、となりの正方形と1本を共有するからです。\nだから正方形 n 個のとき、本数は 4＋3(n−1)＝【3n＋1】本です。「最初に1本置いておき、そこにコの字(3本)を n 回つける」と考えても 3n＋1 が出てきます。\n碁石を正方形の形に並べて、周りだけを数える問題もよく出ます。1辺に n 個並べると、4つの辺で 4n 個ですが、【角の4個を2回ずつ数えている】ので、4n−4 個になります。\nこのように、「重なり(共有)」を引くのが、図形の個数の問題の最大のポイントです。',
        key: '図形の個数は「重なって共有している部分」を2回数えていないか確かめる。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="マッチ棒でつくった正方形3個。最初の1本と、コの字3本ずつのまとまりに分けて数える"><line x1="25" y1="40" x2="25" y2="80" class="cv2"/><path d="M25 40 L65 40 L65 80 L25 80" class="cv"/><path d="M65 40 L105 40 L105 80 L65 80" class="cv"/><path d="M105 40 L145 40 L145 80 L105 80" class="cv"/><text x="10" y="100">最初の1本</text><text x="58" y="30">コの字(3本)×3</text><text x="10" y="122">正方形3個:1＋3×3＝10本</text><text x="10" y="140">正方形 n 個:3n＋1 本</text></svg>',
        ex: [{ q: 'マッチ棒で正方形を横1列につなげてつくる。(1) 正方形を n 個つくるのに必要なマッチ棒の本数を n の式で表しなさい。(2) マッチ棒が 100 本あるとき、正方形は最大で何個つくれますか。', hint: '1個増えるごとに何本増えるかを考えます。(2) は不等式の考え方を使います。', steps: ['1個で4本、2個で7本、3個で10本と、3本ずつ増える。', '本数は 4＋3(n−1)＝3n＋1 本。n＝1 で4本となり合っている。', '(2) 3n＋1＝100 とすると 3n＝99、n＝33。', 'n＝33 のときちょうど 100 本で、34個だと 3×34＋1＝103 本必要になり足りない。'], a: '(1) 3n＋1 本  (2) 33個', check: '3×33＋1＝100 でちょうど使い切ることを確かめます。' }] },
      { h: '2乗や和になる並び', t: '同じ数ずつ増える並び以外で、入試によく出るのが【2乗の並び】と【和の並び】です。\n正方形の形に碁石をしきつめると、1辺が n 個のとき全部で n² 個です。1, 4, 9, 16, 25, … と並びます。差は 3, 5, 7, 9 と2ずつ増えていきます。\n実は、1から順に奇数をたすと 2乗になります。1＝1²、1＋3＝4＝2²、1＋3＋5＝9＝3²。【n 個の奇数の和は n²】です。正方形の碁石の外側に、L字形に奇数個ずつ足していくと、次の正方形になることからも分かります。\n1から n までの自然数の和は【n(n＋1)/2】です。たとえば 1＋2＋…＋10 は、前と後ろから組にすると(1＋10)、(2＋9)、… と和が 11 の組が5つできるので 55 です。式でも 10×11/2＝55 となります。1, 3, 6, 10, 15, … はこの和の並び(三角数)です。\n長方形の形に並べる問題では、たて n 個・横 (n＋1) 個のように、たてと横で個数がずれることがあります。その場合は n(n＋1) のような積で表します。',
        key: 'n 個の奇数の和は n²。1から n までの和は n(n＋1)/2。図にすると理由が見える。',
        ex: [{ q: '1＋2＋3＋…＋n で表される数が 210 になるのは、n がいくつのときですか。', hint: '和の公式 n(n＋1)/2 を使い、二次方程式を立てます。', steps: ['1から n までの和は n(n＋1)/2 なので、n(n＋1)/2＝210。', '両辺に2をかけて n(n＋1)＝420、つまり n²＋n−420＝0。', '420＝20×21 より (n＋21)(n−20)＝0 と因数分解できる。', 'n＝20、−21。n は自然数なので n＝20。'], a: 'n＝20', check: '20×21/2＝210 となり、条件に合います。' }] },
      { h: 'くり返す並びと、あまりの利用', t: '曜日やカレンダー、色が「赤・青・黄・赤・青・黄…」とくり返す問題では、【何個で1周するか(周期)】を見つけ、番号を周期でわった【あまり】で考えます。\nなぜあまりを使うのかというと、1周するごとに同じものにもどるので、何周したかは関係なく、「周の中の何番目か」だけで決まるからです。\n例:赤・青・黄の3つがくり返すとき、50番目は 50÷3＝16 あまり 2 なので、周の中の2番目の「青」です。\nあまりが 0 のときは、周の最後(ここでは黄)になることに注意します。「あまり 0 は1番目」とまちがえやすいので気をつけましょう。\nカレンダーの問題では、たてに並ぶ数は 7 ずつ、横に並ぶ数は 1 ずつ増えます。まん中の数を n とおくと、上下左右は n−7、n＋7、n−1、n＋1 と表せ、たした数の性質(例:5つの和は 5n で5の倍数)を示す問題がよく出ます。',
        key: 'くり返す並びは、周期でわったあまりで考える。あまり0は周の最後。',
        ex: [{ q: '○●●△ の4つの記号が、この順にくり返し並んでいる。(1) 75番目の記号は何ですか。(2) 1番目から75番目までに ● は何個ありますか。', hint: '周期は4です。75 を 4 でわります。', steps: ['周期は ○●●△ の 4 個。', '75÷4＝18 あまり 3 なので、18周した後の3番目。周の3番目は ●。', '1周の中に ● は2個あるので、18周で 2×18＝36 個。', '残りの3個(○●●)の中に ● が2個あるので、36＋2＝38 個。'], a: '(1) ●  (2) 38個', check: '18周で 72 個、残り 3 個で合計 75 個になることを確かめます。' }] },
      { h: '入試の型:説明問題と逆算', t: '高校入試の規則性の問題は、だいたい次の3つの問いで組み立てられています。\n①【具体的な番号を数える】:「5番目の個数を求めよ」。図や表で直接数えられます。ここで規則を確かめます。\n②【n 番目を式で表す】:「n 番目の個数を n を使った式で表せ」。ここまでの方法で文字式にします。\n③【式を使って逆算する】:「個数が 200 個になるのは何番目か」。②の式＝200 という方程式を解きます。\n「〜であることを説明しなさい」という問題もあります。この場合、数をいくつか試すだけでは説明になりません。文字式で一般的に表して、「○の倍数」なら「○×(整数)」の形に変形して示します。\n例:連続する3つの整数の和が3の倍数になることは、n−1、n、n＋1 の和が 3n になることで説明できます。n は整数なので 3n は3の倍数です。',
        key: '入試は「数える → 式にする → 方程式で逆算・文字式で説明」の流れ。説明は具体例ではなく文字式で。',
        ex: [{ q: 'カレンダーで、ある日付の数を n とし、その上・下・左・右の日付と n の5つの数をたす。この和がいつも5の倍数になることを説明しなさい(上下左右の日付はすべて同じ月にあるとする)。', hint: '上下は7ずつ、左右は1ずつちがいます。', steps: ['上の数は n−7、下の数は n＋7、左の数は n−1、右の数は n＋1 と表せる。', '5つの和は n＋(n−7)＋(n＋7)＋(n−1)＋(n＋1) を計算する。', '−7 と ＋7、−1 と ＋1 が打ち消し合い、和は 5n になる。', 'n は整数なので 5n は5の倍数である。'], a: '5つの和は (n−7)＋(n−1)＋n＋(n＋1)＋(n＋7)＝5n。n は整数だから 5n は5の倍数である。', check: '実際に n＝15 のとき 8＋14＋15＋16＋22＝75＝5×15 となり、式と一致します。' }] },
      { h: 'もっと深く:差の差を調べると、式の形が分かる', t: '数の並びの規則を見つけるとき、となりどうしの【差】を調べました。差が一定なら、n 番目の数は an＋b の形(1次式)になります。では、差が一定にならないときは、どうすればよいでしょうか。\nそのときは、【差の差】(2回目の差)を調べます。たとえば 3, 8, 15, 24, … の差は 5, 7, 9 で一定ではありませんが、その差は 2, 2 と一定です。このように2回目の差が一定になる並びの n 番目は、n² をふくむ式(2次式)で表せます。\nしかも、n² の前の数(係数)は【2回目の差の半分】になります。上の例では 2÷2＝1 なので、n 番目は n²＋(何か) と考えます。n² は 1, 4, 9, 16 なので、もとの並び 3, 8, 15, 24 から n² をひくと 2, 4, 6, 8 となり、これは 2n です。よって n 番目は n²＋2n＝n(n＋2) です。\nなぜ「半分」になるのでしょうか。n² の並び 1, 4, 9, 16 の差は 3, 5, 7、その差は 2, 2 です。つまり n² は「2回目の差が2」の並びです。2回目の差が4なら 2n²、6なら 3n² というように、2回目の差は n² の係数の2倍になるのです。\n和の公式 1＋2＋…＋n＝n(n＋1)/2 も、別の見方で確かめられます。同じ和を逆の順にも並べて、たてにたすと、(1＋n)＋(2＋(n−1))＋… と、どの組も n＋1 になり、それが n 組あります。2倍の和が n(n＋1) なので、もとの和はその半分です。\nこのように、「差を調べる」「並べかえてたす」という工夫は、高校で学ぶ【数列】の考え方の入り口になっています。',
        key: '1回目の差が一定→1次式 an＋b。2回目の差が一定→n² をふくむ式で、n² の係数は2回目の差の半分。' },
      { h: '入試ではこう出る:図形の規則と、表の中の数', t: '高校入試の規則性の問題は、①図形(碁石・タイル・マッチ棒)の個数、②表やカレンダーに並んだ数、③くり返しの並び、の3つの型が中心です。どの型も、【数える→式にする→逆算する】の流れで解きます。\n①の図形の問題でよく出るのが、正方形の形に碁石を並べたときの【外側の個数】です。1辺に n 個並べると、4辺で 4n 個に見えますが、4つの角の碁石を2回ずつ数えているので、正しくは 4n−4 個(または 4(n−1) 個)になります。「重なって数えていないか」は、規則性の問題で最もねらわれるひっかけです。\n②の表の数は、【1行に何個並ぶか】が周期の役わりをします。1行に k 個ずつ並ぶ表では、ある数を k でわった商とあまりから、何行目の何列目かが分かります。あまりが0のときは、その行の最後の列になることに注意しましょう。\n③のくり返しの並びは、周期でわったあまりで考えます。\nどの型でも、式ができたら、小さい番号(n＝1、2)を代入して実際の図と合っているかを必ず確かめます。入試では最後の設問ほど配点が高いことが多いので、前の設問でつくった式を使えるように、式は整理して書いておきましょう。',
        key: '正方形の周の碁石は 4n−4(角の重なりに注意)。表の数は「1行の個数」でわった商とあまりで位置が分かる。式は n＝1、2 で必ず確かめる。',
        ex: [
          { q: '碁石を、1辺に n 個ずつ並ぶように正方形の形に並べる(内側には置かない)。\n(1) 使う碁石の個数を n の式で表しなさい。\n(2) 碁石を 96 個使ったとき、1辺に並ぶ碁石は何個ですか。', hint: '1辺に n 個ずつ4辺分あると考えると、4つの角の碁石を何回数えることになるかを考えます。', steps: ['1辺に n 個並ぶので、4辺分を数えると 4n 個。', 'ただし、4つの角の碁石は、となり合う2辺の両方で数えているので、4個多く数えている。', 'よって碁石の個数は 4n−4(個)。n＝2 のとき 4 個、n＝3 のとき 8 個で、図と合う。', '(2) 4n−4＝96 を解くと、4n＝100、n＝25。'], a: '(1) 4n−4 個 (2) 25 個', check: 'n＝25 を 4n−4 に代入すると 100−4＝96 になります。n＝3 の図(角に4個、各辺のまん中に1個ずつで計8個)をかいて、式と合うことも確かめます。' },
          { q: '自然数を 1 から順に、1行に5個ずつ、左から右へ並べていく(1行目は 1〜5、2行目は 6〜10、…)。\n(1) 8行目の左から3列目の数を求めなさい。\n(2) 123 は何行目の左から何列目にありますか。', hint: 'k 行目の最後の数(5列目)は 5k です。', steps: ['k 行目の5列目の数は 5k なので、7行目の最後は 35。', '8行目は 36 から始まるので、3列目は 35＋3＝38。', '(2) 123 を 5 でわると、123＝5×24＋3。商が 24、あまりが 3。', '24行目の最後は 5×24＝120 なので、123 は25行目の3列目。'], a: '(1) 38 (2) 25行目の3列目', check: '25行目は 121, 122, 123, 124, 125 となり、123 が3列目にあることを確かめます。もし数が 125 のようにあまり0なら、25行目の5列目(最後の列)になります。' }
        ] }
    ],
    faq: [
      ['式が合っているか不安なときは?', '作った式に n＝1、2、3 を代入して、表の数と一致するか確かめましょう。3つとも合えば、ほぼまちがいありません。\n入試では、この確かめだけで多くのミスを防げます。'],
      ['いくつか例を挙げて確かめれば「説明」になるの?', 'なりません。例をいくつ挙げても「全部の場合」で正しいとは言えないからです。\n説明問題では、n などの文字を使って一般的な形で表し、「○×(整数)」の形にして示します。例は、説明の後の確かめとして使いましょう。'],
      ['方程式の答えが分数や負の数になったら?', '番号 n は自然数(1、2、3、…)なので、分数や負の数になったら、その数は並びに出てこないということです。\n二次方程式で2つの解が出たときは、自然数のほうだけを答えにします。'],
      ['差も、差の差も一定にならないときは?', '別の規則を疑います。①となりどうしの【比】(何倍になっているか)を調べる、②奇数番目と偶数番目に分けて見る、③分数なら分子と分母を別々に調べる、④いくつかごとにくり返していないか(周期)を見る、などです。\nたとえば 2, 6, 18, 54 は差が 4, 12, 36 で一定になりませんが、比を見るとどれも3倍です。']
    ],
    drill: [
      { lv: 1, q: '4, 9, 14, 19, … と並ぶとき、10番目の数を求めなさい。', a: '49', exp: '差は 5 で一定なので、同じ数ずつ増える並びです。n 番目は 4＋5(n−1)＝5n−1 です。\nn＝10 を代入すると 5×10−1＝49 です。n＝1 で 4、n＝2 で 9 となり、式が並びと合っていることも確かめましょう。' },
      { lv: 1, q: '1, 4, 9, 16, 25, … と並ぶとき、n 番目の数を n の式で表しなさい。', a: 'n²', exp: '1＝1²、4＝2²、9＝3²、16＝4²、25＝5² なので、n 番目は n² です。\n差は 3, 5, 7, 9 と奇数が並び、その差(2回目の差)は2で一定です。2回目の差が2なので、n² の係数は 2÷2＝1 になっています。' },
      { lv: 1, q: '2, 6, 18, 54, □ と並ぶとき、□に当てはまる数を答えなさい。', a: '162', exp: '差は 4, 12, 36 で一定ではありません。そこで比を調べると、6÷2＝3、18÷6＝3、54÷18＝3 で、どれも3倍になっています。\nよって □＝54×3＝162 です。差が一定にならないときは、何倍になっているかを調べるのが次の一手です。' },
      { lv: 2, q: '2, 6, 12, 20, 30, … と並ぶとき、n 番目の数を n の式で表し、10番目の数を求めなさい。', a: 'n 番目:n(n＋1)(n²＋n) 10番目:110', exp: '差は 4, 6, 8, 10、2回目の差は2で一定なので、n² の係数は 2÷2＝1 です。\nもとの並びから n²(1, 4, 9, 16, 25)をひくと 1, 2, 3, 4, 5 となり、これは n です。よって n 番目は n²＋n＝n(n＋1) です。\n2＝1×2、6＝2×3、12＝3×4 のように、となり合う整数の積になっていることでも確かめられます。10番目は 10×11＝110 です。' },
      { lv: 2, q: 'マッチ棒で、正三角形を横1列に、向きを上下交互にしてつなげていく(となり合う三角形は1本を共有する)。マッチ棒が 41 本のとき、正三角形は何個できますか。', a: '20 個', exp: '正三角形1個は 3 本、2個は 5 本、3個は 7 本と、1個増えるごとに 2 本ずつ増えます。2個目からは、となりと1本を共有するので、新しく必要なのは2本だからです。\nよって n 個の正三角形に必要な本数は 3＋2(n−1)＝2n＋1(本)です。\n2n＋1＝41 を解くと n＝20 です。n＝1 で 3 本になることも確かめましょう。' },
      { lv: 2, q: '1, 2, 3, 1, 2, 3, 1, 2, 3, … と並ぶとき、1番目から50番目までの数の和を求めなさい。', a: '99', exp: '「1, 2, 3」の3つがくり返す並びで、1回のくり返しの和は 6 です。\n50÷3＝16 あまり 2 なので、16回くり返したあとに、1, 2 の2つが続きます。\n和は 6×16＋1＋2＝96＋3＝99 です。あまりの部分は、くり返しの最初から数えることに注意しましょう。' },
      { lv: 3, q: '連続する3つの奇数の和は、3の倍数になる。このことを、文字を使って説明しなさい。', a: 'n を整数とすると、連続する3つの奇数は 2n−1、2n＋1、2n＋3 と表せる。その和は (2n−1)＋(2n＋1)＋(2n＋3)＝6n＋3＝3(2n＋1)。2n＋1 は整数だから、3(2n＋1) は3の倍数である。したがって、連続する3つの奇数の和は3の倍数になる。', exp: '奇数は 2n＋1 などの形で表せます。連続する奇数は2ずつ大きくなるので、まん中を 2n＋1 とすると、前後は 2n−1 と 2n＋3 です。\n和を計算したら、「3×(整数)」の形に変形して、かっこの中が整数であることを書きます。これで3の倍数であることが説明できます。\n採点のポイントは、①文字が何を表すか(n は整数)を書いているか、②3つの奇数を正しく表しているか、③3×(整数) の形にして結論を書いているか、です。いくつかの例を計算するだけでは説明になりません。' },
      { lv: 3, q: '白と黒のタイルを並べて、1辺に n 枚の正方形をつくる。外側の1周には黒いタイル、その内側にはすべて白いタイルを並べる(n は3以上)。黒いタイルが 60 枚のとき、白いタイルは何枚ですか。', a: '196 枚', exp: '外側の1周の黒いタイルは、正方形の周の碁石と同じ考え方で、4n−4(枚)です(4つの角を重ねて数えないため)。\n4n−4＝60 を解くと n＝16 です。\n内側の白いタイルは、1辺が n−2 枚の正方形になるので、(16−2)²＝14²＝196(枚)です。\n確かめとして、全体のタイル 16²＝256 枚から黒の 60 枚をひくと 196 枚になり、答えと一致します。' }
    ],
    terms: [['規則性', '数や図形が、あるきまりにしたがって並んでいること'], ['n 番目', '番号を文字 n で表したもの。n は自然数'], ['差', 'となりどうしの数の引き算の結果。差が一定なら同じ数ずつ増える並び'], ['周期', 'くり返す並びで、1周する個数'], ['代入', '文字式の文字に数をあてはめること'], ['自然数', '1、2、3、… のような正の整数'], ['三角数', '1、3、6、10、… のように1から順にたした数。n 番目は n(n＋1)/2']],
    miss: ['n 番目を「最初の数＋増える数×n」としてしまう。1番目はまだ増えていないので、増えた回数は n−1 です。できた式に n＝1 を入れて確かめましょう。', '図形の個数で、角や共有部分を2回数えてしまう。周りの碁石なら 4n ではなく 4n−4 です。小さい番号で実際に数えて式と照らし合わせましょう。', 'くり返しの問題で、あまり 0 を周の1番目とまちがえる。あまり 0 は「ちょうど周が終わったところ」なので周の最後です。', '逆算の方程式で出た n が自然数かどうかを確かめない。分数や負の数なら「並びに出てこない」と判断します。', '説明問題で、具体的な数をいくつか試しただけで終わる。文字式で一般的に示す必要があります。'],
    sum: ['まず1〜4番目くらいを表にして、となりどうしの差を調べる。', '同じ数ずつ増える並びは、n 番目＝最初の数＋増える数×(n−1)。', '図形の個数は、共有している部分を引くのがポイント。', '2乗(n²)や和(n(n＋1)/2)になる並びも知っておく。', 'くり返す並びは周期でわったあまりで考える。', '入試は「数える → 式にする → 逆算・説明」の流れ。式は n＝1、2 で必ず確かめる。'],
    next: '次は「二次方程式」(m_m9)で、逆算のときに出てくる二次方程式を確実に解けるようにしましょう。高校では、この考え方が「数列」という単元につながります。'
  };

  // ===== 中学理科:電流と磁界 =====
  L.s_mag = {
    goal: '電流がつくる磁界、磁界の中で電流が受ける力、電磁誘導のしくみを理解し、向きや大きさがどう変わるかを説明できるようになる。モーター・発電機・直流と交流のちがいも説明できるようになる。',
    intro: '扇風機や洗濯機を回すモーターも、発電所で電気をつくる発電機も、じつは「電流」と「磁石」の組み合わせでできています。電流を流すと磁石のような力が生まれ、反対に磁石を動かすと電流が生まれる。電気と磁気は表と裏の関係にあるのです。この単元では、その3つのしくみを順に学びます。',
    pre: '【電流】は電気の流れで、乾電池の＋極から出て−極にもどる向きに流れると決めています。単位はアンペア(A)です。\n【電圧】は電流を流そうとするはたらきで、単位はボルト(V)です。オームの法則より、電流＝電圧÷抵抗 なので、同じ電熱線なら電圧を大きくすると電流も大きくなります。\n磁石には N極と S極があり、同じ極どうしはしりぞけ合い、ちがう極どうしは引き合います。磁石の力を【磁力】といいます。\n磁力がはたらく空間を【磁界】といいます。磁界の中に方位磁針を置いたとき、【N極がさす向き】を磁界の向きと決めています。\n磁界のようすを表した線を【磁力線】といいます。磁力線は磁石の N極から出て S極に入る向きにかき、線が混んでいるところほど磁界が強いことを表します。',
    secs: [
      { h: '電流のまわりにできる磁界', t: '1本のまっすぐな導線に電流を流し、そのまわりに方位磁針を置くと、針の向きが変わります。電流のまわりに磁界ができたからです。\n磁界は、導線を中心とした【同心円状】にできます。向きは、電流の向きに【右ねじ】を進めるとき、ねじを回す向きです。電流の向きを逆にすると、磁界の向きも逆になります。\n磁界の強さは、【電流が大きいほど強く】、【導線に近いほど強く】なります。\n導線を輪にして何回も巻いたものを【コイル】といいます。コイルに電流を流すと、コイルの内部には同じ向きの磁界が重なって強い磁界ができ、全体として棒磁石のような磁界になります。\nコイルの磁界の向きは、【右手の4本の指を電流の向きに合わせてコイルをにぎったとき、親指の向き】がコイルの内部の磁界の向き(N極になる側)です。コイルの磁界は、電流を大きくする、巻数を多くする、中に鉄心を入れる、ことで強くなります。これを利用したのが【電磁石】です。',
        key: '電流のまわりの磁界は同心円状で、右ねじの向き。電流を逆にすると磁界も逆。コイルは巻数・電流・鉄心で強くなる。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="紙面の奥から手前へ流れる電流のまわりに、反時計回りの同心円状の磁界ができるようす"><circle cx="75" cy="75" r="16" class="cv"/><circle cx="75" cy="75" r="34" class="cv"/><circle cx="75" cy="75" r="52" class="dash"/><circle cx="75" cy="75" r="5" class="pt"/><path d="M109 70 L109 80" class="cv"/><path d="M104 74 L109 68 L114 74" class="cv"/><path d="M41 80 L41 70" class="cv"/><path d="M36 76 L41 82 L46 76" class="cv"/><text x="140" y="40">●:電流が</text><text x="140" y="54">奥から手前へ</text><text x="140" y="84">磁界は</text><text x="140" y="98">反時計回り</text><text x="140" y="130">中心ほど強い</text></svg>',
        ex: [{ q: '南北方向にのばしたまっすぐな導線の真下に方位磁針を置き、導線に南から北へ電流を流した。方位磁針の N極はどちらへ振れるか。', hint: '電流の向きに右ねじを進めたときの回る向きを、導線の下側で考えます。', steps: ['電流は南から北へ流れるので、右ねじを北へ進めることになる。', '北を向いて立ち、時計回りにねじを回す向きを考える。導線の上側では東向き、下側では西向きになる。', '方位磁針は導線の真下にあるので、そこでの磁界の向きは西向き。', '方位磁針の N極は磁界の向きをさすので、西のほうへ振れる。'], a: '西のほうへ振れる。', check: '電流を北から南へ逆にすると、磁界も逆向き(導線の下で東向き)になり、N極は東へ振れることも確かめましょう。' }] },
      { h: '磁界の中で電流が受ける力', t: '磁石の N極と S極の間(磁界の中)に導線を置いて電流を流すと、導線が動きます。磁界の中の電流は【力】を受けるからです。\nなぜ力を受けるのでしょうか。電流がつくる磁界と、磁石の磁界が重なると、一方では磁界が強め合い、反対側では弱め合います。導線は、磁界が強いほうから弱いほうへおし出されるように動きます。\n力の向きは、【電流の向き】と【磁界の向き】の両方で決まります。どちらか一方を逆にすると力は逆向きになり、両方を逆にするともとと同じ向きになります。\n力の大きさは、【電流を大きくする】(電圧を上げる・抵抗の小さい導線にする)と大きくなり、【磁界を強くする】(強い磁石にかえる)と大きくなります。\nまた、導線を磁界と平行に置くと力ははたらきません。力がいちばん大きくなるのは、導線が磁界と垂直になっているときです。',
        key: '力の向きは電流と磁界の向きで決まる。片方を逆にすると逆、両方逆ならもとと同じ。電流・磁界が強いほど力は大きい。',
        ex: [{ q: 'U字形磁石の間につるした導線に電流を流すと、導線は手前に動いた。次の(1)〜(3)のとき、導線はどちらに動くか。(1) 電流の向きを逆にする。(2) 磁石の N極と S極を入れかえる。(3) 電流の向きを逆にし、さらに磁石の極も入れかえる。', hint: '「片方を逆 → 力も逆」「両方を逆 → もとと同じ」のルールを使います。', steps: ['もとは、電流と磁界の向きの組み合わせで手前に動いている。', '(1) 電流だけを逆にしたので、力は逆向きになり、奥へ動く。', '(2) 磁界だけを逆にしたので、力は逆向きになり、奥へ動く。', '(3) 電流も磁界も逆にしたので、逆の逆でもとと同じになり、手前へ動く。'], a: '(1) 奥  (2) 奥  (3) 手前', check: '逆にした回数が奇数なら逆向き、偶数(0回か2回)ならもとと同じ向き、と数えて確かめられます。' }] },
      { h: 'モーターのしくみ', t: '磁界の中で電流が受ける力を利用して、回転を続けるようにした装置が【モーター】です。\n磁石の間にコイルを置いて電流を流すと、コイルの左右の辺は逆向きの電流が流れているので、逆向きの力を受けます。その結果、コイルは回転を始めます。\nところが、そのままではコイルが半回転したところで、力が回転をもどす向きにはたらき、コイルは止まってしまいます。\nそこで使われるのが【整流子】と【ブラシ】です。整流子は、コイルが半回転するごとに、コイルに流れる電流の向きを切りかえます。こうすると、コイルはいつも同じ向きに回る力を受け続けます。\nモーターを速く回すには、電流を大きくする、強い磁石を使う、コイルの巻数を増やす、などの方法があります。モーターは、電気エネルギーを運動エネルギーに変える装置だといえます。',
        key: 'モーターは「磁界の中の電流が受ける力」で回る。整流子が半回転ごとに電流の向きを切りかえて回転を続けさせる。' },
      { h: '電磁誘導と発電機', t: 'コイルに棒磁石を近づけたり遠ざけたりすると、コイルに電流が流れます。コイルの中の【磁界が変化】すると電圧が生じ、電流が流れるのです。この現象を【電磁誘導】、流れる電流を【誘導電流】といいます。\n大切なのは「変化」です。磁石をコイルの中に入れたまま止めておくと、磁界は強くても変化しないので、電流は流れません。\n誘導電流の向きは、磁石を【近づけるときと遠ざけるときで逆】になります。また、磁石の極を逆(N極→S極)にしても逆になります。\n誘導電流を大きくするには、①磁石を【速く動かす】、②【磁力の強い磁石】を使う、③コイルの【巻数を多くする】、の方法があります。どれも、コイルの中の磁界の変化を大きくする方法です。\nコイルや磁石を回転させて、電磁誘導で電流をつくり続ける装置が【発電機】です。発電機は、運動エネルギーを電気エネルギーに変える装置で、モーターとはちょうど逆のはたらきをします。発電所の多くは、タービンで発電機を回して電気をつくっています。',
        key: '電磁誘導は「コイルの中の磁界の変化」で起こる。止めると流れない。速く・強い磁石・巻数多いほど大きい。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="棒磁石のN極をコイルに近づけると、検流計の針が振れる"><rect x="12" y="58" width="34" height="22" class="bx"/><rect x="46" y="58" width="34" height="22" class="bx"/><text x="22" y="73">S</text><text x="58" y="73">N</text><path d="M86 69 L104 69" class="cv2"/><path d="M98 64 L105 69 L98 74" class="cv2"/><path d="M112 52 L112 86 M122 52 L122 86 M132 52 L132 86 M142 52 L142 86 M152 52 L152 86" class="cv"/><path d="M112 52 Q117 46 122 52 Q127 46 132 52 Q137 46 142 52 Q147 46 152 52" class="cv"/><path d="M112 86 L112 118 L136 118 M152 86 L152 118 L144 118" class="ax"/><circle cx="140" cy="118" r="10" class="bx"/><line x1="140" y1="118" x2="146" y2="111" class="cv2"/><text x="10" y="104">近づける</text><text x="158" y="122">検流計</text><text x="96" y="140">止めると流れない</text></svg>',
        ex: [{ q: 'コイルに棒磁石の N極を近づけると、検流計の針が右に振れた。次のとき、針はどちらに振れるか。(1) N極を遠ざける。(2) S極を近づける。(3) S極を遠ざける。(4) N極をコイルの中に入れたまま止める。', hint: '「近づける⇔遠ざける」「N極⇔S極」のどちらかを変えると逆になります。', steps: ['基準は「N極を近づける → 右」。', '(1) 動かす向きだけを逆にしたので左。', '(2) 極だけを逆にしたので左。', '(3) 動かす向きも極も逆にしたので、逆の逆で右。', '(4) 磁界が変化しないので電流は流れず、針は振れない(0 を指す)。'], a: '(1) 左  (2) 左  (3) 右  (4) 振れない', check: '変えた条件の数が1つなら逆、2つならもとと同じ。止めたときだけは電流が流れない、と整理して確かめます。' }] },
      { h: '直流と交流', t: '乾電池から流れる電流は、いつも同じ向きに流れます。このような電流を【直流】といいます。\n一方、家庭のコンセントから流れる電流は、向きと大きさが周期的にくり返し変わります。このような電流を【交流】といいます。発電所の発電機は、コイルや磁石が回転するたびに誘導電流の向きが入れかわるので、交流をつくり出します。\n交流で、1秒間にくり返す変化の回数を【周波数】といい、単位はヘルツ(Hz)です。日本では、おおよそ静岡県の富士川と新潟県の糸魚川付近を境に、【東日本が 50 Hz、西日本が 60 Hz】です。これは、明治時代に東と西で異なる国の発電機を輸入したことに由来するといわれています。\n交流の利点は、【変圧器で電圧を簡単に変えられる】ことです。発電所からは高い電圧で送り出し(送電中の損失が少なくなる)、家庭の近くで低い電圧にもどして使います。\n直流と交流は、発光ダイオードで見分けられます。発光ダイオードは決まった向きにしか電流を流さないので、交流につないで左右に速く動かすと、点灯と消灯をくり返す点線のように見えます。直流ではつながった線に見えます。',
        key: '直流は向きが一定、交流は向きと大きさが周期的に変わる。周波数は東日本 50 Hz・西日本 60 Hz。交流は変圧しやすい。',
        ex: [{ q: '発光ダイオードを乾電池につないだものと、交流電源につないだものを、暗い部屋で左右にすばやく動かした。それぞれどのように見えるか。また、その理由を説明しなさい。', hint: '発光ダイオードは、電流が決まった向きに流れたときだけ光ります。', steps: ['発光ダイオードは、決まった向きに電流が流れたときだけ光る。', '乾電池は直流なので、電流はいつも同じ向きに流れ、光り続ける。動かすとつながった光の線に見える。', '交流は電流の向きが周期的に入れかわるので、光る時間と消える時間がくり返す。', '動かすと、光った所と消えた所が交互に並び、点線のように見える。'], a: '乾電池:つながった光の線に見える(直流は向きが一定で光り続けるため)。交流:点線のように見える(電流の向きが周期的に変わり、点灯と消灯をくり返すため)。', check: '交流の周波数が大きいほど点灯・消灯のくり返しが速くなり、点線の間かくがつまって見えることも合わせて理解しておきましょう。' }] },
      { h: 'もっと深く:電流と磁界は、たがいに生み出し合う', t: 'この単元で学んだ3つの現象は、ばらばらのように見えますが、すべて【電流と磁界の関係】でつながっています。\n①電流が流れると、そのまわりに磁界ができる(電流の磁界)。②磁界の中で電流が流れると、電流が力を受ける(モーターの原理)。③コイルの中の磁界が変化すると、電流が流れる(電磁誘導、発電機の原理)。①と③は、電流から磁界、磁界の変化から電流と、ちょうど逆向きの関係になっています。\nエネルギーの見方で整理すると、【モーター】は電気エネルギーを運動エネルギーに変える装置、【発電機】は運動エネルギーを電気エネルギーに変える装置です。しくみはよく似ていて、実際にモーターの軸を手で回すと、発電機として電流を取り出すことができます。\nでは、電磁誘導で電流が流れるとき、エネルギーはどこから来るのでしょうか。磁石をコイルに近づけて誘導電流が流れると、コイルは電磁石になります。このとき、コイルは【磁石の動きをじゃまする向き】の磁界をつくります(N極を近づけると、近づけた側が N極になって押し返す)。だから、磁石を動かし続けるには力が必要で、その仕事が電気エネルギーに変わるのです。手回し発電機に豆電球をつなぐと、つながないときより手ごたえが重くなるのはこのためです。\nこのしくみは、交流の利点ともつながります。家庭への送電で使う【変圧器】は、鉄心に巻いた2つのコイルのうち、一方に交流を流して磁界を変化させ続け、もう一方のコイルに電磁誘導で電流を起こします。直流では磁界が変化しないので、変圧器ははたらきません。交流が「電圧を変えやすい」のは、電磁誘導を利用できるからなのです。',
        key: '電流→磁界、磁界＋電流→力、磁界の変化→電流。誘導電流は磁石の動きをじゃまする向きの磁界をつくるので、発電には仕事が必要。変圧器は電磁誘導を使うので交流でしか使えない。' },
      { h: '入試ではこう出る:向きの判断と、大きさの比較', t: '高校入試の電流と磁界の問題は、①【向き】を答える問題と、②【大きさ】を比べる問題の2つに分かれます。\n①の向きの問題では、「電流の向き」「磁界(磁石の極)の向き」のどちらを変えたかを整理します。どちらか一方を逆にすると力(または誘導電流)の向きは逆になり、両方を逆にするともとと同じになります。電磁誘導では、「N極を近づける」と「S極を遠ざける」が同じ向き、「N極を遠ざける」と「S極を近づける」が同じ向きです。\n②の大きさの問題は、オームの法則の単元とつながっています。磁界の中の導線が受ける力は、【電流が大きいほど大きい】ので、回路の抵抗を小さくしたり、電圧を大きくしたりすると、導線の振れは大きくなります。抵抗を直列・並列につないだときの電流を計算させる問題がよく出ます。\n電磁誘導の大きさは、磁石を動かす速さ、磁石の強さ、コイルの巻数で決まります。「棒磁石をコイルの中に入れたまま止める」と、磁界が変化しないので電流は流れません。止めた状態をひっかけに使う問題は定番です。\n解くときは、問題文の条件を「電流:そのまま/逆」「磁界:そのまま/逆」のように表にして、変化した条件の数を数えると、迷わずに答えられます。',
        key: '向きは「逆にした条件の数」で判断(1つ→逆、2つ→もとと同じ)。力の大きさは電流の大きさで決まるので、オームの法則で電流を計算して比べる。',
        ex: [
          { q: '電源装置(電圧 6 V)、抵抗器、U字形磁石の間につるした導線(ブランコ)をつないだ回路で、導線の振れの大きさを調べる。抵抗器を次のア〜エのようにつなぎかえたとき、振れが大きい順に並べなさい。ただし、電源の電圧は 6 V のまま変えず、導線の抵抗は考えないものとする。\nア 10 Ω の抵抗器1個 イ 20 Ω の抵抗器1個 ウ 10 Ω と 20 Ω を並列につなぐ エ 10 Ω と 20 Ω を直列につなぐ', hint: '導線が受ける力は電流が大きいほど大きくなります。それぞれの回路全体に流れる電流を求めましょう。', steps: ['ア:電流＝6÷10＝0.6 A。', 'イ:電流＝6÷20＝0.3 A。', 'ウ:並列なので、それぞれの抵抗器に 6 V がかかる。0.6＋0.3＝0.9 A。', 'エ:直列なので全体の抵抗は 30 Ω。電流＝6÷30＝0.2 A。', '電流が大きい順に、ウ(0.9 A)＞ア(0.6 A)＞イ(0.3 A)＞エ(0.2 A)。'], a: 'ウ → ア → イ → エ', check: '並列につなぐと全体の抵抗は 10 Ω より小さくなり、直列につなぐと 30 Ω に大きくなることから、ウが最大、エが最小になるのは筋が通っています。' },
          { q: '棒磁石を、N極を下にしてコイルの真上から落とし、コイルの中を通りぬけさせた。磁石がコイルに入るとき、検流計の針は右に振れた。磁石がコイルから出ていくとき、針はどちらに振れるか。理由とともに答えなさい。', hint: 'コイルの中を通る磁界(下向き)が、入るときと出るときで、強くなるのか弱くなるのかを考えます。', steps: ['N極を下にした棒磁石が上から近づくと、コイルの中を通る下向きの磁界がだんだん強くなる。このとき針は右に振れた。', '磁石がコイルを通りぬけて下へ遠ざかるとき、コイルの中を通る下向きの磁界はだんだん弱くなる。', '磁界の変化の向き(強くなる→弱くなる)が逆になるので、誘導電流の向きも逆になる。', 'よって、出ていくときは針が左に振れる。'], a: '左に振れる。磁石が入るときはコイルの中の磁界が強くなり、出ていくときは弱くなるので、磁界の変化が逆になり、誘導電流の向きも逆になるから。', check: '磁石がコイルの中にあって磁界がほとんど変化しない瞬間には、針はほぼ0にもどります。「右に振れる→0付近→左に振れる」という流れになることを確かめます。' }
        ] }
    ],
    faq: [
      ['モーターと発電機は、どうちがうの?', 'つくりはよく似ていますが、エネルギーの変わり方が逆です。モーターは「電流を流す → 回る」で、電気エネルギーを運動エネルギーに変えます。発電機は「回す → 電流が流れる」で、運動エネルギーを電気エネルギーに変えます。\n実際に、小型のモーターの軸を手で回すと、発電機として電流をとり出せます。'],
      ['右ねじや右手のにぎり方を忘れてしまったら?', '入試では、向きそのものより「片方を逆にしたら逆」「両方を逆にしたらもとと同じ」を問う問題が多く出ます。まずはこのルールを確実にしましょう。\nそのうえで、問題文に与えられた最初の結果を基準にして、何を逆にしたかを数えれば、たいていの問題は解けます。'],
      ['磁石をコイルの中で止めると、なぜ電流が流れないの?', '電磁誘導は、コイルの中の磁界が「変化」したときに起こる現象だからです。磁石が止まっていると、磁界は強くても変化していません。\n磁石を動かし続けるか、コイルを回し続けることで、磁界が変化し続け、電流が流れ続けます。これが発電機の考え方です。'],
      ['フレミングの左手の法則は覚えたほうがいいの?', '教科書によって扱いがちがいますが、知っていると力の向きをすばやく判断できます。左手の中指・人差し指・親指をたがいに直角に開き、【中指=電流】、【人差し指=磁界】、【親指=力】の向きに合わせます(「電・磁・力」と覚えます)。\nただし、入試の多くの問題は「電流か磁界の一方を逆にすると力も逆」という考え方だけで解けます。法則を使うときは、右手と左手を取りちがえないように注意しましょう。']
    ],
    drill: [
      { lv: 1, q: 'コイルの中の磁界が変化したときにコイルに流れる電流を何といいますか。', a: '誘導電流', exp: 'コイルの中の磁界が変化すると、コイルに電圧が生じて電流が流れます。この現象を電磁誘導、流れる電流を誘導電流といいます。\n磁界が変化しているときだけ流れることが大切なポイントです。' },
      { lv: 1, q: '東日本の家庭に送られている交流の周波数は何 Hz ですか。', a: '50 Hz', exp: '日本では、東日本(おおむね静岡県の富士川から新潟県の糸魚川あたりより東)が 50 Hz、西日本が 60 Hz です。\n周波数は、1秒間に電流の向きが変わる周期をくり返す回数で、50 Hz なら1秒間に50回くり返します。' },
      { lv: 1, q: '直流モーターで、コイルが半回転するごとに電流の向きを切りかえる部品を何といいますか。', a: '整流子(とブラシ)', exp: '整流子は、ブラシと接しながらコイルといっしょに回り、半回転ごとにコイルに流れる電流の向きを切りかえます。\nこれによって、コイルが受ける力の向きがいつも同じ回転方向になり、モーターは回り続けることができます。' },
      { lv: 2, q: 'コイルと棒磁石を使って、誘導電流を大きくする方法を3つ答えなさい。', a: '磁石を速く動かす。磁力の強い磁石を使う。コイルの巻数を多くする。', exp: '誘導電流は、コイルの中の磁界の変化が大きく、速いほど大きくなります。\n磁石を速く動かすと、短い時間で磁界が大きく変化します。強い磁石を使うと、変化する磁界そのものが大きくなります。巻数を多くすると、1巻きごとに生じる電圧が合わさって大きくなります。' },
      { lv: 2, q: 'コイルに電流を流すと、コイルの左はしが N極になった。電流の向きを逆にすると、コイルの左はしは何極になりますか。', a: 'S極', exp: 'コイルにできる磁界の向きは、電流の向きで決まります。電流を逆にすると磁界の向きも逆になるので、左はしは S極になります。\n右手の4本の指を電流の向きに合わせてコイルをにぎると、親指の向きが N極になる、という方法で確かめられます。' },
      { lv: 2, q: '磁界の中の導線(ブランコ)に 3 V の電圧を加えると 0.5 A の電流が流れた。電圧を 6 V にすると、流れる電流は何 A になり、導線の振れはどうなりますか。', a: '1.0 A になり、振れは大きくなる。', exp: '導線をふくむ回路の抵抗は 3÷0.5＝6 Ω です。抵抗が変わらなければ、電流は電圧に比例するので、6 V のときは 6÷6＝1.0 A です。\n磁界の中で導線が受ける力は電流が大きいほど大きいので、電流が2倍になると振れも大きくなります。力の向きは電流の向きを変えていないので同じです。' },
      { lv: 3, q: '変圧器は交流では電圧を変えられるが、直流ではそのままでは使えない。その理由を「磁界」という語を使って説明しなさい。', a: '変圧器は、一方のコイルに流れる電流がつくる磁界の変化によって、もう一方のコイルに電磁誘導で電流を起こすしくみである。交流は向きと大きさが変わり続けるので磁界も変化し続けるが、直流は電流が一定で磁界が変化しないため、電磁誘導が起こらないから。', exp: '電磁誘導が起こるのは、コイルの中の磁界が変化しているときだけです。\n交流は電流の向きと大きさが周期的に変わるので、それがつくる磁界も変わり続け、もう一方のコイルに電流を起こし続けます。直流は電流が一定なので、スイッチを入れた瞬間などをのぞき、磁界が変化しません。\n採点のポイントは、①電磁誘導を使うしくみであること、②交流では磁界が変化し、直流では変化しないこと、の2点を書いているかです。' },
      { lv: 3, q: '手回し発電機に豆電球をつないでハンドルを回すと、何もつながずに回すときより手ごたえが重くなる。その理由を、エネルギーの移り変わりにふれて説明しなさい。', a: '豆電球をつなぐと回路に誘導電流が流れ、電気エネルギーが取り出される。このエネルギーは、手がハンドルを回す仕事(運動エネルギー)から変換されたものなので、電流が流れる分だけ、より大きな力で回す必要があるから。', exp: '何もつながないと回路が切れているので、電流は流れず、電気エネルギーはほとんど取り出されません。豆電球をつなぐと電流が流れ、豆電球で光や熱のエネルギーになります。\nエネルギーは何もないところからは生まれないので、その分の仕事を、ハンドルを回す手がしなければなりません。コイルに流れる誘導電流がつくる磁界が、回転をじゃまする向きの力を生むためです。\n採点のポイントは、①電流が流れると電気エネルギーが取り出されること、②それが手の仕事から変換されること、を結びつけているかです。' }
    ],
    terms: [['磁界', '磁力がはたらく空間。方位磁針の N極がさす向きが磁界の向き'], ['磁力線', '磁界のようすを表す線。N極から出て S極に入る'], ['コイル', '導線を輪にして何回も巻いたもの'], ['電磁石', 'コイルの中に鉄心を入れ、電流を流すと磁石になるようにしたもの'], ['整流子', 'モーターで、半回転ごとにコイルの電流の向きを切りかえる部品'], ['電磁誘導', 'コイルの中の磁界が変化して電圧が生じ、電流が流れる現象'], ['誘導電流', '電磁誘導によって流れる電流'], ['周波数', '交流が1秒間にくり返す変化の回数。単位はヘルツ(Hz)']],
    miss: ['磁石をコイルの中で止めても電流が流れると思ってしまう。「磁界が強い」と「磁界が変化する」を混同するからです。電磁誘導は変化が必要、と覚えましょう。', '電流の向きと磁界の向きを両方逆にしたとき、力も逆になると答えてしまう。逆にした回数を数え、2回なら「もとと同じ」と判断します。', '導線の上と下で、磁界の向きが逆になることを忘れる。同心円状の磁界をかいて、方位磁針がどの位置にあるかを図で確かめましょう。', '東日本と西日本の周波数を逆に覚える。「東は 50、西は 60(西のほうが大きい)」と、数字の大小とセットで覚えましょう。'],
    sum: ['電流のまわりには同心円状の磁界ができ、向きは右ねじの回る向き。コイルは棒磁石のような磁界をつくる。', '磁界の中の電流は力を受ける。向きは電流と磁界の向きで決まり、大きさは電流・磁界が強いほど大きい。', 'モーターは整流子で電流の向きを切りかえ、同じ向きに回り続ける。', 'コイルの中の磁界が変化すると誘導電流が流れる(電磁誘導)。発電機はこのしくみ。', '直流は向きが一定、交流は向きと大きさが周期的に変わる。周波数は東日本 50 Hz・西日本 60 Hz。'],
    next: '次は「入試レベル:中学理科の総合」(sx_jh)で、電力・発熱量と組み合わせた計算問題に進みましょう。高校の物理では、この内容が「電磁誘導」「交流」としてさらに深く学べます。'
  };

  // ===== 中学理科:自然と人間 =====
  L.s_env = {
    goal: '食物連鎖と生物の数量のつり合い、分解者のはたらきと物質の循環を説明できるようになる。人間の活動が自然環境にあたえる影響と、発電に使うエネルギー資源の特徴を説明できるようになる。',
    intro: '森の落ち葉は、なぜ何年たっても積もり続けて山にならないのでしょうか。それは、目に見えない小さな生物が、落ち葉を少しずつ分解して土にもどしているからです。自然界では、植物・動物・微生物が「食べる・食べられる」「つくる・こわす」の関係でつながり、物質がぐるぐると回っています。この単元では、そのつながりと、そこに人間がどう関わっているかを学びます。',
    pre: '【光合成】は、植物が光のエネルギーを使って、二酸化炭素と水からデンプンなどの養分をつくるはたらきです。このとき酸素が出ます。\n【呼吸】は、生物が酸素を使って養分を分解し、生きるためのエネルギーをとり出すはたらきです。このとき二酸化炭素と水が出ます。植物も、昼も夜も呼吸をしています。\n【有機物】は、デンプン・タンパク質・脂肪のように、炭素をふくみ、燃やすと二酸化炭素が出る物質です。生物のからだは主に有機物でできています。二酸化炭素や水、無機塩類など、それ以外の物質を【無機物】といいます。\n草食動物は植物を、肉食動物はほかの動物を食べて養分を得ています。動物は自分で有機物をつくることができません。\n【エネルギー】は、ものを動かしたり温めたりする能力です。電気・熱・光・運動・化学(物質がもつ)などの種類があり、たがいに移り変わります。',
    secs: [
      { h: '食物連鎖と食物網', t: '自然界の生物は、「食べる・食べられる」の関係でつながっています。たとえば、草 → バッタ → カエル → ヘビ → タカ のような関係です。このつながりを【食物連鎖】といいます。\n実際には、1種類の動物が何種類もの生物を食べ、何種類もの生物に食べられています。そのため、食物連鎖は1本の鎖ではなく、網の目のように複雑にからみ合っています。これを【食物網】といいます。\nある地域に住むすべての生物と、それをとりまく水・空気・土・光などの環境を、ひとまとまりとしてとらえたものを【生態系】といいます。森林・草原・湖・海などは、それぞれ1つの生態系です。\n食物連鎖は、陸上だけでなく水中にもあります。海では、植物プランクトン → 動物プランクトン → 小さな魚 → 大きな魚 のようにつながっています。\n食物連鎖のはじまりは、ほとんどの場合、光合成をする植物(または植物プランクトン)です。',
        key: '「食べる・食べられる」のつながりが食物連鎖。実際には網の目のような食物網になっている。' },
      { h: '生産者・消費者と数量のつり合い', t: '生態系の生物は、役割によって次のように分けられます。\n【生産者】…光合成によって、無機物(二酸化炭素と水)から有機物をつくり出す生物。植物や植物プランクトンです。\n【消費者】…生産者がつくった有機物を、直接または間接に食べて養分にする生物。草食動物や肉食動物です。\n生物の数量を食物連鎖の順に積み上げると、一般に、生産者がいちばん多く、上位の消費者ほど少なくなる【ピラミッド形】になります。なぜなら、食べた養分の一部しか自分のからだにならず、多くは呼吸で使われたり、ふんとして出たりするからです。\nこの数量のつり合いは、一時的にくずれても、ふつうはもとにもどります。たとえば草食動物が増えると、植物は食べられて減り、肉食動物はえさが増えて増えます。すると今度は草食動物が減り、植物は増え、肉食動物は減って、やがてもとのつり合いにもどります。\nただし、人間の活動や外来生物、大規模な災害などで変化が大きすぎると、もとにもどらないこともあります。',
        key: '数量は生産者がいちばん多いピラミッド形。一時的に変化しても、ふつうはもとのつり合いにもどる。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="生物の数量のピラミッド。下から植物、草食動物、肉食動物の順に少なくなる"><path d="M90 20 L120 20 L135 52 L75 52 Z" class="tr"/><path d="M75 56 L135 56 L152 90 L58 90 Z" class="tr"/><path d="M58 94 L152 94 L172 130 L38 130 Z" class="tr"/><text x="94" y="42">肉食</text><text x="86" y="78">草食動物</text><text x="70" y="117">植物(生産者)</text><text x="148" y="34">少ない</text><text x="178" y="120">多い</text><line x1="190" y1="104" x2="190" y2="44" class="ax"/><path d="M186 50 L190 42 L194 50" class="ax"/></svg>',
        ex: [{ q: '植物 → 草食動物 → 肉食動物 の食物連鎖で、何かの原因で肉食動物が急に減った。この後、植物・草食動物の数量はそれぞれどう変化するか。順を追って説明しなさい。', hint: '肉食動物が減ると、まずだれが助かるかを考えます。', steps: ['肉食動物が減ると、食べられる草食動物が減らなくなり、草食動物が増える。', '草食動物が増えると、食べられる植物は減る。', '草食動物は、えさの植物が減ることと、えさが増えた肉食動物がふたたび増えることで、やがて減る。', '草食動物が減ると植物は増え、全体としてもとのつり合いにもどっていく。'], a: '草食動物が増え、植物が減る。その後、えさ不足や肉食動物の回復で草食動物が減り、植物が増えて、やがてもとのつり合いにもどる。', check: '「すぐ上の生物」と「すぐ下の生物」への影響を1段ずつ順に考えたかを確かめます。' }] },
      { h: '分解者のはたらき', t: '生物の死がいやふん、落ち葉などの有機物は、そのまま残り続けるわけではありません。これらを食べて、最終的に二酸化炭素や水、無機塩類などの無機物にまで分解する生物がいます。こうした生物を【分解者】といいます。\n分解者の中心は、カビやキノコなどの【菌類】と、乳酸菌や大腸菌などの【細菌類】です。菌類や細菌類は、呼吸によって有機物を無機物に分解し、生きるためのエネルギーを得ています。\n土の中の小動物(ミミズ、ダンゴムシ、トビムシなど)も、落ち葉などを食べて細かくし、分解を助けるので、分解者にふくめて考えます。\n分解者がつくった無機物は、ふたたび植物が根から吸収したり、光合成に使ったりします。分解者がいなければ、地上は死がいや落ち葉でうまり、植物は養分を得られなくなってしまいます。\n分解者のはたらきは、下水処理場でも利用されています。微生物に汚れ(有機物)を分解させて、水をきれいにしているのです。',
        key: '分解者(菌類・細菌類・土の中の小動物)は、有機物を無機物にもどし、物質を植物に返す。',
        ex: [{ q: '林の土を水に入れてかき混ぜ、上ずみ液を2つのビーカーA・Bに分けた。Bの上ずみ液だけ十分に沸とうさせてから冷ました。A・Bにデンプン溶液を加えてふたをし、数日置いた後、ヨウ素液を加えた。結果を予想し、そこからわかることを答えなさい。', hint: 'ヨウ素液はデンプンがあると青紫色になります。沸とうさせると微生物はどうなるでしょう。', steps: ['A では、上ずみ液の中の微生物が生きているので、デンプンを分解する。', 'そのため A にはデンプンが残らず、ヨウ素液の色は変化しない。', 'B は沸とうさせたので、微生物は死んでいて、デンプンは分解されない。', 'B にはデンプンが残り、ヨウ素液で青紫色になる。', 'A と B のちがいは微生物が生きているかどうかだけなので、土の中の微生物がデンプンを分解したといえる。'], a: 'A:色が変わらない。B:青紫色になる。土の中の微生物(菌類・細菌類)がデンプンを分解したことがわかる。', check: 'B のように、調べたい条件(微生物の有無)以外を同じにした実験を対照実験といいます。B があることで、結論がはっきり言えることを確かめましょう。' }] },
      { h: '炭素と酸素の循環', t: '生物のからだをつくる炭素は、生態系の中をめぐっています。\n大気中の【二酸化炭素】は、生産者の光合成によってとりこまれ、有機物になります。有機物は食物連鎖によって消費者へ移り、死がいやふんは分解者へ移ります。\n生産者・消費者・分解者は、どれも【呼吸】をして有機物を分解し、二酸化炭素を大気中にもどしています。こうして炭素は「二酸化炭素 → 有機物 → 二酸化炭素」と形を変えながら循環しています。\n酸素は、光合成によって大気中に出され、すべての生物の呼吸によってとりこまれます。\nこの循環のバランスに大きく関わっているのが人間の活動です。石油や石炭などの【化石燃料】は、大昔の生物の死がいが変化した有機物で、燃やすと二酸化炭素が出ます。大量の化石燃料を燃やすと、大気中の二酸化炭素が増え、循環のバランスがくずれます。',
        key: '炭素は光合成でとりこまれ、食物連鎖で移り、呼吸でもどる。化石燃料の大量消費でバランスがくずれる。',
        ex: [{ q: '生態系の炭素の循環で、「大気中の二酸化炭素を減らすはたらき」と「大気中に二酸化炭素を出すはたらき」をそれぞれ答えなさい。また、それぞれ生産者・消費者・分解者のどれが行うか答えなさい。', hint: '光合成と呼吸の、とり入れるものと出すものを思い出します。', steps: ['光合成は二酸化炭素をとり入れて有機物をつくるので、大気中の二酸化炭素を減らす。', '光合成を行うのは生産者(植物)だけである。', '呼吸は有機物を分解して二酸化炭素を出すので、大気中に二酸化炭素を出す。', '呼吸は生産者・消費者・分解者のすべてが行う。'], a: '減らすはたらき:光合成(生産者)。出すはたらき:呼吸(生産者・消費者・分解者のすべて)。', check: '植物も呼吸をしていることを忘れていないかを確かめます。植物は光合成と呼吸の両方を行います。' }] },
      { h: '人間の活動と自然環境の保全', t: '人間は、自然からさまざまなめぐみを受ける一方で、自然環境に大きな影響もあたえています。\n【地球温暖化】:化石燃料の大量消費や森林の減少によって、大気中の二酸化炭素などの温室効果ガスが増え、地球の平均気温が上がっていると考えられています。海面の上昇や異常気象との関係が心配されています。\n【外来生物】:人間によってもともと住んでいなかった地域に持ちこまれた生物を外来生物といいます。オオクチバス(ブラックバス)やアライグマなどは、在来の生物を食べたり、すみかをうばったりして、生態系のつり合いをくずすことがあります。\n【水の汚れ】:生活排水などで川や湖に有機物が増えすぎると、水がよごれます。川の水のよごれの程度は、そこに住む生物(【指標生物】)で調べることができます。たとえばカワゲラやサワガニはきれいな水に、アメリカザリガニやサカマキガイはよごれた水にも見られる生物です。\nこうした問題に対して、森林や干潟の保護、外来生物の持ちこみの規制、排水の処理、自然とのバランスを考えた開発など、自然環境を守る取り組みが進められています。',
        key: '温暖化・外来生物・水の汚れなどの問題がある。指標生物で水のよごれを調べ、保全の取り組みを進める。',
        ex: [{ q: 'ある池に外来生物の肉食魚が持ちこまれ、増えた。この池の生態系にどのような影響が考えられるか。食物連鎖のことばを使って説明しなさい。', hint: '外来生物は、もとの食物網にはいなかった新しい消費者です。', steps: ['外来の肉食魚は、池にもともといた小魚やエビなどを食べる。', '在来の生物には、新しい天敵に対する備えがないことが多く、数が大きく減ることがある。', 'その小魚をえさにしていた在来の生物も、えさが減って影響を受ける。', '食物網全体のつり合いがくずれ、もとにもどらなくなるおそれがある。'], a: '外来の肉食魚が在来の小魚などを食べて数を大きく減らし、それをえさにする生物にも影響が広がって、池の食物網のつり合いがくずれるおそれがある。', check: '影響が「食べられる生物」だけでなく、「それを食べていた生物」にまで広がることを書けたかを確かめます。' }] },
      { h: 'エネルギー資源と発電', t: '私たちが使う電気は、さまざまなエネルギーを電気エネルギーに変えてつくられています。どの発電方法にも、よい点と課題があります。\n【火力発電】:石油・石炭・天然ガスなどの化石燃料を燃やし、その熱で水を水蒸気に変え、タービンを回して発電します。化学エネルギー → 熱エネルギー → 運動エネルギー → 電気エネルギー と移り変わります。日本の発電の中心ですが、化石燃料には限りがあり、二酸化炭素を多く出します。\n【水力発電】:ダムにためた水を落とし、水車を回して発電します。位置エネルギー → 運動エネルギー → 電気エネルギー。二酸化炭素を出しませんが、ダムをつくれる場所が限られます。\n【原子力発電】:ウランなどの核燃料が核分裂するときの熱で水蒸気をつくり発電します。二酸化炭素をほとんど出しませんが、放射線を出す物質の管理や、使用済み燃料の処理が大きな課題です。\n【再生可能エネルギー】:太陽光・風力・地熱・バイオマス(生物資源)など、使ってもなくならず、二酸化炭素の排出が少ないエネルギーです。太陽光や風力は、天候によって発電量が変わることが課題です。\nどの発電方法でも、エネルギーの一部は利用できない熱などとして失われます。もとのエネルギーのうち、目的のエネルギーに変えられた割合を【変換効率】といいます。',
        key: '発電はエネルギーの変換。化石燃料は限りがあり CO₂ を出す。再生可能エネルギーは天候に左右される課題がある。',
        ex: [{ q: '次の発電方法について、もとになるエネルギーと、二酸化炭素を出すかどうかを答えなさい。(1) 火力発電 (2) 水力発電 (3) 太陽光発電', hint: '何を電気に変えているのかを考えます。', steps: ['(1) 火力発電は化石燃料のもつ化学エネルギーを、熱 → 運動 → 電気と変える。燃料を燃やすので二酸化炭素を出す。', '(2) 水力発電は高い所の水がもつ位置エネルギーを、運動 → 電気と変える。発電のときに二酸化炭素は出さない。', '(3) 太陽光発電は光エネルギーを直接電気エネルギーに変える。発電のときに二酸化炭素は出さない。'], a: '(1) 化学エネルギー・出す (2) 位置エネルギー・出さない (3) 光エネルギー・出さない', check: '発電中に「何かを燃やしているか」で、二酸化炭素を出すかどうかを判断できることを確かめます。' }] },
      { h: 'もっと深く:物質は循環し、エネルギーは流れていく', t: '生態系の中の炭素や酸素は、生物と大気の間を【循環】していました。では、エネルギーも同じように循環しているのでしょうか。答えは「いいえ」です。\nエネルギーの出発点は【太陽の光】です。生産者は光合成で光エネルギーを有機物の【化学エネルギー】としてたくわえます。そのエネルギーは、食物連鎖を通して消費者へ、死がいや排出物を通して分解者へと移っていきます。しかし、どの生物も、生きるために呼吸で有機物を分解してエネルギーを使い、最後は【熱】として周りに出してしまいます。熱になったエネルギーを、生物がふたたび利用することはできません。\nつまり、物質は形を変えながら生態系の中を回り続けますが、エネルギーは太陽から入って熱として出ていく【一方通行の流れ】なのです。生態系が続くには、太陽の光が毎日届き続けることが欠かせません。\nこの考え方で、数量のピラミッドの形も説明できます。ある段階の生物がとりこんだエネルギーの多くは、その生物自身の呼吸などで使われてしまい、次の段階(食べる側)に渡るのは一部だけです。だから、上の段階ほど支えられる生物の量は少なくなり、ピラミッドの形になるのです。\n食物連鎖は、有害な物質の移り方にも関係します。分解されにくく体の外に出にくい物質は、食べる・食べられるの関係を通して、上の段階の生物ほど体内に高い濃度でたまります。これを【生物濃縮】といいます。工場の排水にふくまれていた有機水銀(メチル水銀)が魚介類の体内に濃縮され、それを食べた人々に健康被害が出た【水俣病】は、その代表的な例です。',
        key: '物質は循環するが、エネルギーは太陽→化学エネルギー→熱と一方通行で流れる。上の段階ほど受けとるエネルギーが少ないのでピラミッド形になる。分解されにくい物質は生物濃縮される。' },
      { h: '入試ではこう出る:循環の図と、数量変化の読み取り', t: '高校入試のこの単元では、①炭素(物質)の循環を示す【矢印の図】、②生物の数量の変化を示す【グラフ】、③分解者のはたらきを確かめる【対照実験】がよく出ます。\n①の矢印の図では、矢印が「気体(二酸化炭素・酸素)の出入り」なのか、「有機物の移動」なのかを区別します。大気から生産者へ向かう二酸化炭素の矢印は【光合成】、すべての生物から大気へ向かう矢印は【呼吸】です。生物から生物への矢印は、食べる・食べられる、または死がい・排出物による有機物の移動です。「呼吸の矢印は生産者からも出ている」ことを見落とすミスが多いので注意しましょう。\n②の数量変化のグラフでは、ある生物が増えたり減ったりしたあと、【すぐに起こる変化】と【その後の変化】を順にたどります。食べる側は、えさが増えると少しおくれて増え、えさが減ると少しおくれて減ります。グラフのどの山が先に来ているかが、食べる・食べられるの関係を見分ける手がかりです。\n③の対照実験では、【調べたい条件以外をすべて同じにする】ことが大切です。土の上ずみ液を沸とうさせるのは、微生物だけを死なせて、そのほかの条件をそろえるためです。\n記述問題では、「生産者・消費者・分解者」「光合成・呼吸」「有機物・無機物」などの用語を正しく使えているかが採点のポイントになります。',
        key: '大気→生産者の矢印=光合成、すべての生物→大気=呼吸。数量グラフは「食べる側は少しおくれて増減する」で関係を見分ける。',
        ex: [
          { q: '生態系の炭素の循環で、次の①〜⑤の矢印のうち、(1) 光合成、(2) 呼吸、(3) 有機物の移動 にあたるものをそれぞれすべて選びなさい。\n① 大気 → 植物 ② 植物 → 大気 ③ 植物 → 草食動物 ④ 草食動物 → 大気 ⑤ 動物の死がい → 菌類・細菌類', hint: '気体の二酸化炭素として移るのか、生物の体をつくる有機物として移るのかを、矢印ごとに考えます。', steps: ['① 大気中の二酸化炭素を植物がとりこむのは光合成。', '② 植物も生きるために呼吸をして二酸化炭素を大気に出す。④ 草食動物の呼吸も同じ。', '③ 草食動物が植物を食べることで、植物の体の有機物が移る。', '⑤ 死がいの有機物が分解者に移る。分解者も呼吸で二酸化炭素を出す(図にあれば分解者→大気の矢印)。'], a: '(1) ① (2) ②、④ (3) ③、⑤', check: '「光合成は植物だけ、呼吸はすべての生物」が守られているかを確かめます。② を光合成と考えて選ばなかったり、植物は呼吸しないと考えたりしていないか注意します。' },
          { q: 'ある地域で、植物・草食動物・肉食動物の3種類の生物の数量を調べた。グラフから、生物 A が急に増えた直後に生物 B が少しおくれて増え、同じころ生物 C は減っていった。A、B、C は、植物・草食動物・肉食動物のどれにあたるか答えなさい。', hint: '「食べる側はえさが増えると少しおくれて増える」「食べられる側は、食べる側が増えると減る」を使います。', steps: ['A が増えると、少しおくれて B が増えた。B は A を食べる側だと考えられる。', 'A が増えると C は減った。C は A に食べられる側だと考えられる。', 'よって、食べられる順に C → A → B の食物連鎖になっている。', '3種類の生物にあてはめると、C が植物、A が草食動物、B が肉食動物。'], a: 'A:草食動物 B:肉食動物 C:植物', check: 'C(植物)→A(草食動物)→B(肉食動物)と並べて、「A が増える→ A に食べられる C が減る、A を食べる B が増える」という流れが筋の通るものかを確かめます。' }
        ] }
    ],
    faq: [
      ['分解者は、消費者とはちがうの?', '分解者も、ほかの生物がつくった有機物を養分にしているので、広い意味では消費者の一部です。\nただし、死がいやふんなどの有機物を最終的に無機物にまで分解し、物質を生産者に返すという特別な役割があるので、区別して「分解者」とよびます。'],
      ['植物は光合成で二酸化炭素を減らすのに、なぜ森林を守るだけでは温暖化は止まらないの?', '植物は光合成をする一方で、呼吸もしていますし、枯れれば分解者によって二酸化炭素にもどされます。\nまた、化石燃料を燃やして出る二酸化炭素の量はとても多いので、森林を守ることに加えて、化石燃料の使用を減らすことが必要だと考えられています。'],
      ['再生可能エネルギーがよいなら、なぜ全部それにしないの?', '太陽光や風力は、天候や時間帯によって発電量が大きく変わるので、それだけでは必要なときに必要な量の電気を安定して届けるのがむずかしいからです。\nそのため、いくつかの発電方法を組み合わせたり、電気をためる技術を開発したりする取り組みが進められています。'],
      ['もし分解者がいなくなったら、生態系はどうなるの?', '生物の死がいや排出物が分解されずにたまり続けます。すると、有機物が二酸化炭素や水、窒素をふくむ無機物などにもどらないので、植物が育つのに必要な養分が土にもどらなくなります。\n植物が育たなければ、それを食べる消費者も生きられません。分解者は目立ちませんが、物質の循環を支える欠かせない存在なのです。']
    ],
    drill: [
      { lv: 1, q: '生態系の中で、光合成によって無機物から有機物をつくり出す生物を何といいますか。', a: '生産者', exp: '植物や、水中の植物プランクトン(けい藻など)のように、光合成で無機物(二酸化炭素と水)から有機物をつくる生物を生産者といいます。\n生産者がつくった有機物が、食物連鎖を通してほかのすべての生物の栄養のもとになります。' },
      { lv: 1, q: '分解者にあたる生物のなかまを2つ答えなさい。', a: '菌類(カビ・キノコなど)、細菌類(乳酸菌・大腸菌など)', exp: '菌類や細菌類は、死がいや排出物にふくまれる有機物を無機物に分解します。\n土の中のミミズやダンゴムシなどの小動物も、落ち葉などを食べて細かくし、分解にかかわるので、分解者としてあつかうことがあります。' },
      { lv: 1, q: '発電に利用される再生可能エネルギーを3つ答えなさい。', a: '(例)太陽光、風力、地熱(ほかに水力、バイオマスなど)', exp: '再生可能エネルギーは、自然の中でくり返し補給され、使ってもなくならないエネルギーです。太陽光・風力・地熱・水力・バイオマス(生物由来の資源)などがあります。\n石油・石炭・天然ガスなどの化石燃料や、ウランを使う原子力は、資源に限りがあるので再生可能エネルギーにはふくまれません。' },
      { lv: 2, q: '晴れた日の昼、植物は二酸化炭素を出していますか。光合成と呼吸の関係にふれて説明しなさい。', a: '呼吸によって二酸化炭素を出しているが、光合成でとりこむ二酸化炭素の量のほうが多いので、全体としては二酸化炭素をとり入れているように見える。', exp: '植物は、昼も夜も一日中呼吸をしていて、そのたびに二酸化炭素を出しています。\n昼は光合成もさかんに行い、呼吸で出す量より多くの二酸化炭素をとりこみます。そのため、差し引きでは二酸化炭素をとり入れ、酸素を出しているように見えます。\n「昼は光合成だけ、夜は呼吸だけ」と考えるのは誤りです。' },
      { lv: 2, q: '生物の数量のピラミッドで、上の段階(肉食動物)ほど数量が少なくなる理由を、エネルギーにふれて説明しなさい。', a: '各段階の生物がとりこんだエネルギーの多くは、その生物自身の呼吸などで使われて熱として出ていき、次の段階に渡るのは一部だけなので、上の段階ほど支えられる生物の量が少なくなるから。', exp: '食べた有機物のエネルギーは、すべてが体をつくるのに使われるわけではありません。多くは、生きるための呼吸などで使われ、熱として周りに出ていきます。\nそのため、食べる側に渡るエネルギーは、食べられる側がもっていたエネルギーの一部だけになります。段階が上がるたびに使えるエネルギーが減るので、ピラミッド形になります。' },
      { lv: 2, q: '分解されにくい有害な物質が、食物連鎖の上の段階の生物ほど体内に高い濃度でたまる現象を何といいますか。また、そうなる理由を説明しなさい。', a: '生物濃縮。分解されにくく体の外に出にくい物質は、食べた生物の体内にたまり、その生物を食べる上の段階の生物は、たくさんの生物を食べるたびに物質をとりこむので、濃度がどんどん高くなるから。', exp: '肉食動物は、一生の間に多くの草食動物を食べます。もし食べた生物の体に分解されにくい物質がふくまれていれば、それが少しずつ体にたまっていきます。\n水俣病は、工場の排水にふくまれていた有機水銀(メチル水銀)が魚介類の体内に濃縮され、それを食べた人々に被害が出た公害病です。生物濃縮は、食物連鎖と環境問題を結びつける重要な考え方です。' },
      { lv: 3, q: '化石燃料を大量に燃やすと、生態系の炭素の循環のつり合いがくずれるのはなぜですか。説明しなさい。', a: '化石燃料は、大昔の生物の体の炭素が長い間地下にたくわえられたものである。それを短い期間に大量に燃やすと、ふだんの循環には入っていなかった炭素が二酸化炭素として大気中に出され、光合成でとりこまれる量より増えるので、大気中の二酸化炭素がふえ続けるから。', exp: 'ふつうの生態系では、光合成でとりこまれる二酸化炭素と、呼吸で出される二酸化炭素がほぼつり合っています。\n石油・石炭・天然ガスは、大昔の生物の遺がいなどが長い年月をかけて変化したもので、その炭素は長い間、循環の外の地下にしまわれていました。それを短い期間に燃やすと、循環に新しく炭素が加わることになり、つり合いがくずれます。\n採点のポイントは、①化石燃料の炭素がもともと循環の外にあったこと、②燃やすと二酸化炭素が大気中にふえること、の2点です。' },
      { lv: 3, q: 'デンプンをふくむ寒天培地に、林の土を水に入れてかき混ぜた上ずみ液を少量たらし、ふたをして数日置いた。その後ヨウ素液をかけると、全体は青紫色になったが、微生物が集まって育った部分(コロニー)の周りだけ色が変わらなかった。この結果から分かることを説明しなさい。', a: 'コロニーの周りではデンプンがなくなっていることから、土の中の微生物(菌類・細菌類)が、デンプンを分解したことが分かる。', exp: 'ヨウ素液は、デンプンがあると青紫色になります。全体が青紫色になったのは培地にデンプンが残っているからで、コロニーの周りだけ色が変わらなかったのは、そこにデンプンがなくなっているからです。\nデンプンをなくしたのは、そこで育った微生物だと考えられます。つまり、土の中の微生物は、有機物であるデンプンを分解するはたらきをもつ分解者だと分かります。\n採点のポイントは、①ヨウ素液の色の意味(デンプンの有無)、②微生物がデンプンを分解したこと、を結びつけて書いているかです。' }
    ],
    terms: [['生態系', 'ある地域の生物と、それをとりまく環境をひとまとまりとしてとらえたもの'], ['食物連鎖', '「食べる・食べられる」の関係による生物のつながり'], ['食物網', '食物連鎖が網の目のように複雑にからみ合ったもの'], ['生産者', '光合成で無機物から有機物をつくる生物(植物など)'], ['消費者', 'ほかの生物を食べて有機物を得る生物(動物)'], ['分解者', '死がいやふんなどの有機物を無機物に分解する生物(菌類・細菌類など)'], ['外来生物', '人間によって、もともと住んでいなかった地域に持ちこまれた生物'], ['再生可能エネルギー', '太陽光・風力・水力・地熱など、使ってもなくならないエネルギー']],
    miss: ['植物は光合成だけをして、呼吸はしないと思ってしまう。昼は光合成が目立つからです。植物も昼夜を問わず呼吸していることを、炭素の循環の図で確かめましょう。', '分解者を「菌類だけ」と考え、細菌類や土の中の小動物を入れ忘れる。分解者の例は「カビ・キノコ(菌類)、乳酸菌・大腸菌(細菌類)、ミミズ・ダンゴムシ」とセットで覚えましょう。', '数量のつり合いの問題で、変化した生物の「上」か「下」の一方しか考えない。1段上と1段下への影響を、順番に矢印でかいて考えましょう。', '原子力発電の燃料ウランを、化石燃料だと思ってしまう。化石燃料は「大昔の生物の死がいからできた燃料(石油・石炭・天然ガス)」です。'],
    sum: ['生物は食物連鎖でつながり、実際には食物網になっている。', '生物の数量は生産者がいちばん多いピラミッド形で、変化してもふつうはもとのつり合いにもどる。', '分解者(菌類・細菌類・土の中の小動物)が有機物を無機物にもどし、物質は循環する。', '炭素は光合成でとりこまれ、呼吸でもどる。化石燃料の大量消費はこのバランスをくずす。', '温暖化・外来生物・水の汚れなどの問題があり、自然環境の保全が必要。', '発電はエネルギーの変換。発電方法ごとに、よい点と課題がある。'],
    next: '次は高校の「生態系(生物基礎)」(s_eco)で、生態系のバランスや物質循環を、さらにくわしく学びましょう。発電とエネルギーの計算は「入試レベル:中学理科の総合」(sx_jh)で練習できます。'
  };

  // ===== 中学社会:日本の諸地域 =====
  L.c_jregion = {
    goal: '日本の7つの地方を、それぞれ1つの「中心となる考え方」から整理し、自然・産業・くらしのつながりを、理由をつけて説明できるようになる。',
    intro: '日本の地理をただ暗記しようとすると、地名や産物の数が多すぎて混乱します。そこで中学校では、地方ごとに【中心となる考え方】(テーマ)を1つ決め、そのテーマから地方の特色を説明していきます。たとえば九州なら「自然環境」、関東なら「人口や都市」です。テーマを軸にすると、ばらばらに見えた知識が「だから、こうなっている」と1本の線でつながります。',
    pre: '日本は、北海道・東北・関東・中部・近畿・中国四国・九州の【7地方区分】で分けることが多いです。都道府県の位置と、どの地方に入るかを白地図で確かめておきましょう。\n日本の気候は、季節風(モンスーン)の影響を強く受けます。冬は大陸から北西の季節風がふき、日本海側に雪を降らせます。夏は太平洋から南東の季節風がふき、太平洋側に雨を多く降らせます。\n日本の周りには、暖流の【黒潮(日本海流)】と【対馬海流】、寒流の【親潮(千島海流)】と【リマン海流】が流れています。暖流と寒流がぶつかる所を【潮目】といい、よい漁場になります。\n地形では、川が山地から平地に出る所にできる【扇状地】(水はけがよく果樹園に向く)と、河口にできる【三角州】(低く平らで水田や都市になる)のちがいが大切です。\n農業の用語も確認しておきます。【促成栽培】は温暖な気候を生かして出荷時期を早める栽培、【抑制栽培】は夏でもすずしい気候を生かして出荷時期をおくらせる栽培、【近郊農業】は大都市の近くで新鮮な野菜などをつくる農業です。',
    secs: [
      { h: '地方を「中心となる考え方」で見る', t: 'なぜテーマを決めるのでしょうか。1つの地方には、気候・地形・農業・工業・人口・文化など、たくさんの情報があります。全部を同じ重さで覚えるより、その地方の特色がいちばんよく表れるテーマを軸にして、ほかの情報をつなげたほうが、理解しやすく忘れにくいからです。\n教科書によってテーマの組み合わせは少しずつちがいますが、代表的なのは次のような組み合わせです。九州:【自然環境】、中国・四国:【交通・他地域との結びつき】、近畿:【歴史的背景・環境保全】、中部:【産業】、関東:【人口や都市・村落】、東北:【生活・文化(伝統)】、北海道:【自然環境と産業(開拓の歴史)】。\n使い方の基本は「テーマ → 原因 → 結果」です。たとえば九州なら「火山が多い(自然環境)→ 火山灰の台地が広がる → 稲作に向かず、畜産や畑作がさかん」とつなげます。\n入試では「なぜその地域でその産業がさかんなのか」を説明させる問題がよく出ます。テーマから理由をたどる練習は、そのまま記述問題の練習になります。',
        key: '地方ごとのテーマを軸に、「テーマ → 原因 → 結果(産業・くらし)」とつなげて覚える。',
        tmap: { title: '7地方区分と中心となる考え方(模式図)', cols: 5, rows: 4,
          cells: [
            ['北海道', 'b', 5, 1, 1, 1, '自然環境と開拓'],
            ['東北', 'gr', 5, 2, 1, 1, '伝統・生活文化'],
            ['中部', 'o', 4, 2, 1, 2, '産業'],
            ['関東', 'r', 5, 3, 1, 1, '人口・都市'],
            ['近畿', 'g', 3, 3, 1, 1, '歴史・環境保全'],
            ['中国・四国', 'k', 2, 3, 1, 2, '交通・結びつき'],
            ['九州', 'p', 1, 4, 1, 1, '自然環境']
          ],
          legend: [['p', '九州'], ['k', '中国・四国'], ['g', '近畿'], ['o', '中部'], ['r', '関東'], ['gr', '東北'], ['b', '北海道']],
          note: '位置関係だけを表した模式図です(実際の形・広さではありません)。テーマは教科書によって少しちがうことがあります。' } },
      { h: '九州地方:火山と温暖な気候(自然環境)', t: '九州地方の特色は、【火山】と【温暖な気候】という自然環境から説明できます。\n九州には、阿蘇山・雲仙岳・桜島などの火山があります。阿蘇山には、噴火でできた大きなくぼ地(【カルデラ】)があり、その中に町や田畑があります。火山は噴火の災害をもたらす一方で、温泉や【地熱発電】(大分県など)、観光というめぐみももたらします。\n九州南部には、火山の噴出物が積もった【シラス台地】が広がります。シラスは水を通しやすく、稲作には向きません。そのため、さつまいもや茶などの畑作や、豚・肉用牛・にわとりなどの【畜産】がさかんになりました。\n北部の【筑紫平野】は九州有数の稲作地帯で、米の裏作に小麦などをつくる【二毛作】が行われています。温暖な【宮崎平野】では、ビニールハウスを使ってピーマンやきゅうりの出荷を早める促成栽培がさかんです。\n九州は台風の通り道にもあたり、大雨による土砂災害も起こりやすい地域です。南西の【沖縄県】は、さんご礁の海や独自の文化をもち、観光業がさかんです。一方で、アメリカ軍の基地が多く集中していることが課題になっています。\n工業では、明治時代に官営の【八幡製鉄所】がつくられ、北九州工業地帯(地域)が発展しました。工業化の中で公害も起こりました(熊本県の【水俣病】など)が、現在は環境の改善やリサイクルに力を入れています。',
        key: '九州:火山(カルデラ・シラス台地・地熱)と温暖な気候(促成栽培)。シラス台地は稲作に向かず畜産・畑作。',
        ex: [{ q: '鹿児島県や宮崎県で畜産がさかんな理由を、土地の特徴にふれて説明しなさい。', hint: 'シラス台地の土の性質を考えます。', steps: ['九州南部には、火山の噴出物が積もったシラス台地が広がっている。', 'シラスは水を通しやすく、水をためる必要がある稲作には向かない。', 'そこで、乾いた土地でも育つさつまいもなどの畑作や、飼料作物を生かした畜産が発達した。', 'まとめると「シラス台地 → 稲作に不向き → 畜産・畑作」とつなげる。'], a: '水はけのよいシラス台地が広がり稲作に向かないため、畑作や、豚・肉用牛などを育てる畜産が発達したから。', check: '答えに「シラス台地」と「稲作に向かない(水はけがよい)」の両方が入っているかを確かめます。' }] },
      { h: '中国・四国地方:交通と他地域との結びつき', t: '中国・四国地方は、【山陰】(中国山地の北側)、【瀬戸内】(中国山地と四国山地の間)、【南四国】(四国山地の南側)の3つに分けると気候がよくわかります。山陰は冬に北西の季節風で雪や雨が多く、南四国は夏に南東の季節風と台風で雨が多く、瀬戸内は2つの山地に季節風がさえぎられて一年中雨が少ない地域です。瀬戸内では、昔から【ため池】をつくって水不足に備えてきました。\nこの地方のテーマは【交通・他地域との結びつき】です。本州と四国の間には、3つのルートで【本州四国連絡橋】がかけられました。児島・坂出ルート(瀬戸大橋)、神戸・鳴門ルート(明石海峡大橋など)、尾道・今治ルート(瀬戸内しまなみ海道)です。\n橋ができて移動時間が大きく短くなり、通勤・通学や観光、物の輸送が便利になりました。その一方で、買い物客などが大都市に吸い寄せられ、地方の商店街がおとろえる【ストロー現象】も起こりました。\n瀬戸内海沿岸には【瀬戸内工業地域】があります。海上輸送に便利で、塩田のあと地などの広い土地があったため、岡山県倉敷市の水島地区などに石油化学コンビナートがつくられました。\n中国山地や四国山地の山間部では、若い人が都市に出ていき、人口が大きく減る【過疎】が進んでいます。高齢化も進み、地域の生活を維持することが課題です。そこで、地域の特産品やインターネット販売、観光を生かした【町おこし・村おこし】の取り組みが行われています。\n農業では、温暖な高知平野でなす・ピーマンの促成栽培、愛媛県の日当たりのよい斜面でみかんの栽培が行われています。',
        key: '中国・四国:本州四国連絡橋で結びつきが強まった一方、ストロー現象や山間部の過疎も。瀬戸内は少雨でため池。',
        ex: [{ q: '本州四国連絡橋の開通は、四国の人々のくらしにどのような影響をあたえたか。よい面と課題の両方を説明しなさい。', hint: '移動が便利になると、人や物はどちらへ動くでしょうか。', steps: ['よい面:本州との間の移動時間が短くなり、通勤・通学や観光、物の輸送が便利になった。', '農産物などを大都市へ早く運べるようになり、出荷が増えた。', '課題:人々が買い物などで大阪や岡山などの大都市へ出かけやすくなった。', 'その結果、地元の商店街の客が減るストロー現象が起こった。'], a: 'よい面:移動時間が短くなり、通勤・通学・観光や農産物の輸送が便利になった。課題:買い物客などが大都市に吸い寄せられ、地元の商店がおとろえるストロー現象が起こった。', check: '「交通が便利になる」という同じ原因から、よい面と課題の両方が生まれていることを確かめます。' }] },
      { h: '近畿地方:歴史的景観と環境保全', t: '近畿地方は、古代から都がおかれた地域で、【京都】や【奈良】には寺院・神社など多くの文化財があり、世界遺産にも登録されています。この地方のテーマは【歴史的背景・環境保全】です。\n古い町なみを守ることと、人々が便利にくらすことは、ときにぶつかります。京都市では、建物の高さやデザイン、看板の色などを制限する【景観条例】を定め、歴史的な町なみを守っています。伝統的な木造の住宅(町家)を、店や宿として生かす取り組みも行われています。\n【琵琶湖】は日本最大の湖で、「近畿の水がめ」として京都・大阪など多くの人々の生活を支えています。かつて生活排水などの影響で、プランクトンが大量に発生する【赤潮】が起こりました。そこで、りんをふくむ合成洗剤を使わない住民運動が広がり、滋賀県は条例を定めて水質の改善に取り組みました。\n大阪湾の沿岸には【阪神工業地帯】が広がります。内陸部には、高い技術をもつ【中小企業】の工場が多く集まっているのが特色です。臨海部の工場のあと地では、再開発が進められています。\n紀伊半島の【紀伊山地】は雨が多く、すぎ・ひのきがよく育つため、古くから林業がさかんです(吉野すぎ・尾鷲ひのきなど)。しかし、輸入木材の増加や林業で働く人の高齢化が課題になっています。',
        key: '近畿:古都の景観を条例で守る。琵琶湖は住民運動と条例で水質改善。阪神工業地帯は中小企業が多い。',
        ex: [{ q: '京都市が、建物の高さや看板の色を制限する条例を定めているのはなぜか。説明しなさい。', hint: '京都の町がもっている価値を考えます。', steps: ['京都には、古くからの寺院・神社や町なみが多く残っている。', '高い建物や派手な看板が増えると、歴史的な景観がそこなわれる。', '景観は、住民のほこりであると同時に、観光客をひきつける大切な資源でもある。', 'そのため、条例で開発に一定の制限をかけて、景観を守っている。'], a: '寺院・神社や古い町なみなどの歴史的な景観を守り、住民の生活の場や観光の資源として次の世代に伝えるため。', check: '「開発」と「保全」が対立することと、条例でその調整をしていることが書けているかを確かめます。' }] },
      { h: '中部地方:地域ごとに異なる産業', t: '中部地方は本州の中央にあり、東西に広く、高い山々(日本アルプス)があるため、【東海】・【中央高地】・【北陸】の3つの地域で気候も産業も大きくちがいます。テーマは【産業】です。\n【東海】は太平洋側で、冬も比較的温暖です。愛知県を中心とする【中京工業地帯】は、豊田市などの自動車工業を中心に、製造品出荷額が全国で最も多い工業地帯です。静岡県の沿岸には【東海工業地域】があり、浜松市のオートバイ・楽器などが有名です。農業では、静岡県の茶、渥美半島で夜に照明を当てて開花をおくらせる【電照菊】の栽培などが行われています。\n【中央高地】は内陸にあり、夏と冬、昼と夜の気温差が大きい地域です。甲府盆地では、扇状地の水はけのよさを生かして、ぶどう・ももの栽培がさかんです。長野県ではりんご、八ヶ岳のふもとなどの高原では、夏のすずしさを生かしたレタス・キャベツなどの【高原野菜】の抑制栽培がさかんです。諏訪盆地では、きれいな水と空気を生かして時計やカメラなどの精密機械工業が発達し、現在は電子部品などの工業も行われています。\n【北陸】は日本海側で、冬に雪が多い地域です。雪で冬に農作業ができないため、米だけをつくる【水田単作】が中心で、新潟県などは全国有数の米どころです。雪の間の副業として始まった【地場産業】や伝統産業も発達しました。輪島塗(石川県)、鯖江市の眼鏡フレーム(福井県)、燕市の金属洋食器(新潟県)などが代表です。',
        key: '中部:東海=自動車(中京工業地帯)・茶・電照菊、中央高地=果樹・高原野菜・精密機械、北陸=水田単作・地場産業。',
        flow: { title: '中部地方の3つの地域', cols: 3, head: ['東海', '中央高地', '北陸'],
          rows: [
            [['太平洋側・温暖', 'o'], ['内陸・気温差大', 'gr'], ['日本海側・雪が多い', 'b']],
            [['中京工業地帯', 'r', 1, '自動車・出荷額全国一'], ['果樹・高原野菜', 'gr', 1, 'ぶどう・もも・レタス'], ['水田単作', 'b', 1, '米どころ']],
            [['茶・電照菊', 'o', 1, '静岡・渥美半島'], ['精密機械・電子部品', 'k', 1, '諏訪盆地など'], ['地場産業', 'g', 1, '輪島塗・眼鏡フレーム']]
          ],
          legend: [['o', '東海'], ['gr', '中央高地'], ['b', '北陸']] },
        ex: [{ q: '長野県の高原で、夏にレタスなどの野菜をつくって出荷すると有利なのはなぜか。説明しなさい。', hint: 'ほかの産地が出荷しにくい時期を考えます。', steps: ['高原は標高が高く、夏でもすずしい。', 'レタスなどはすずしい気候でよく育ち、暑い平地では夏に育てにくい。', 'そのため、ほかの産地からの出荷が少ない夏に、高原から出荷できる。', '出荷量が少ない時期なので、高い値段で売りやすい。これを抑制栽培という。'], a: '夏でもすずしい高原の気候を生かし、平地の産地の出荷が少ない夏に出荷できるため、高い値段で売りやすいから。', check: '「すずしい気候」と「ほかの産地が出荷しにくい時期(値段が高い)」の2点が入っているかを確かめます。促成栽培と出荷時期の考え方が逆であることも確認しましょう。' }] },
      { h: '関東地方:人口の集中と都市', t: '関東地方には日本の人口の約3分の1が集まり、首都【東京】を中心に巨大な都市圏が広がっています。テーマは【人口や都市・村落】です。\n東京には、国会や中央官庁などの政治の中心機能と、大企業の本社や銀行などの経済の中心機能が集まっています。情報・出版などの産業も集中しています。このように、さまざまな機能が東京に集中することを【一極集中】といいます。\n東京の都心には、昼に通勤・通学で多くの人が集まります。そのため都心では、【昼間人口】(昼にいる人の数)が【夜間人口】(住んでいる人の数)より多くなります。反対に、周辺の埼玉県・千葉県・神奈川県などでは、夜間人口のほうが多くなります。\n人口の集中は、通勤ラッシュ、住宅の不足、ごみの増加、都心の気温が周りより高くなる【ヒートアイランド現象】などの問題を生みました。対策として、横浜市の「みなとみらい21」などの再開発や、筑波研究学園都市などへの機能の分散が進められてきました。\n工業では、東京湾の西側に【京浜工業地帯】、東側に石油化学や鉄鋼の【京葉工業地域】があります。高速道路が整備されると、内陸部に工業団地がつくられ、【北関東工業地域】が発展しました。\n関東平野は、火山灰が積もった赤土の【関東ローム】におおわれた台地が多く、畑作が中心です。大消費地に近い千葉県や茨城県などでは、新鮮な野菜や花を短時間で出荷できる【近郊農業】がさかんです。群馬県の嬬恋村では、高原のすずしさを生かしてキャベツを栽培しています。',
        key: '関東:人口と機能が東京に集中(一極集中)。都心は昼間人口＞夜間人口。周辺に近郊農業・北関東工業地域。',
        ex: [{ q: '東京都の中心部では昼間人口が夜間人口より多く、となりの埼玉県では夜間人口のほうが多い。その理由を説明しなさい。', hint: '人々がどこに住み、どこへ通っているかを考えます。', steps: ['東京の中心部には、会社・官庁・学校などが多く集まっている。', 'しかし都心は地価が高く、住宅をもつのがむずかしいため、周辺の県に住む人が多い。', '周辺の県に住む人々が、昼に通勤・通学で東京の中心部へ移動する。', 'そのため、都心では昼間人口が多く、周辺の県では夜間人口が多くなる。'], a: '東京の中心部には会社や学校が集まる一方、多くの人が周辺の県に住み、昼に通勤・通学で都心へ移動するから。', check: '「住む場所」と「通う場所」が分かれていることが説明に入っているかを確かめます。' }] },
      { h: '東北地方と北海道地方:伝統文化と、自然を生かした産業', t: '【東北地方】のテーマは【生活・文化(伝統)】です。中央の【奥羽山脈】を境に、日本海側は冬に雪が多く、太平洋側は夏に冷たく湿った北東の風【やませ】がふくことがあります。やませが続くと日照不足と低温で稲が十分に育たない【冷害】が起こります。人々は、冷害に強い品種を開発するなどして米づくりを続け、庄内平野・秋田平野・仙台平野などは全国有数の米どころになっています。\n東北では、厳しい自然の中で、豊作をいのる夏祭りや伝統工芸が受けつがれてきました。青森ねぶた祭・秋田竿燈まつり・仙台七夕まつりは東北三大祭りとよばれます。南部鉄器(岩手県)、天童将棋駒(山形県)、会津塗(福島県)などの【伝統的工芸品】は、冬の農作業ができない時期の副業として発達したものも多くあります。\n果樹栽培もさかんで、青森県のりんご、山形県のさくらんぼ(おうとう)は、生産量が全国一です。三陸海岸の南部は【リアス海岸】で、波がおだやかな湾でわかめ・かきなどの養殖が行われています。沖合は親潮と黒潮がぶつかる潮目で、よい漁場です。2011年の【東日本大震災】では大きな被害を受け、現在も復興の取り組みが続いています。\n【北海道地方】は、冷帯(亜寒帯)の気候で冬の寒さが厳しく、梅雨がほとんどありません。冬のオホーツク海沿岸には流氷がおし寄せます。北海道にはもともと先住民族の【アイヌの人々】がくらしていました。明治時代に【開拓使】がおかれ、【屯田兵】などによって本格的な開拓が進められました。\n石狩平野は、もともと泥炭地で農業に不向きでしたが、ほかの土地から土を運び入れる【客土】や品種改良によって、全国有数の稲作地帯になりました。十勝平野では、同じ畑で年ごとにちがう作物をつくる【輪作】による大規模な畑作(じゃがいも・てんさい・小麦など)が、根釧台地では、すずしい気候を生かした【酪農】が行われています。知床は世界自然遺産に登録され、自然を守りながら観光に生かすエコツーリズムが進められています。',
        key: '東北:やませと冷害、祭り・伝統的工芸品、果樹(りんご・さくらんぼ)。北海道:開拓の歴史、客土で稲作、輪作・酪農。',
        ex: [{ q: '東北地方の太平洋側で、夏に「やませ」がふき続けると、稲作にどのような影響が出るか。理由とともに説明しなさい。', hint: 'やませの性質(冷たい・湿っている)から考えます。', steps: ['やませは、夏に太平洋側にふく、冷たく湿った北東の風である。', '冷たい風のため気温が上がらず、湿った風で雲や霧が発生して日照時間が少なくなる。', '稲は夏の高温と日光で育つので、低温と日照不足で実りが悪くなる。', 'このようにして米の収穫量が大きく減る被害を冷害という。'], a: '冷たく湿ったやませのために気温が上がらず日照も不足し、稲が十分に育たないため、米の収穫量が減る冷害が起こる。', check: '「低温」と「日照不足」の2つの原因が入っているか、結果として「冷害」ということばが使えているかを確かめます。' }] },
      { h: 'もっと深く:気候と地形から、全国の産業をつなげて読む', t: '地方ごとのテーマを学んだあとは、それを【日本全体の自然のしくみ】でつなげてみましょう。すると、ばらばらに覚えていたことが、理由のある知識に変わります。\nまず【季節風】です。冬は北西の季節風が日本海で水蒸気をふくみ、日本列島の山地にぶつかって、日本海側に多くの雪を降らせます。山をこえた風は乾いて、太平洋側は晴れの日が多くなります。夏は南東の季節風が太平洋側に雨をもたらします。北陸で水田単作が多いのも、冬に雪で田畑が使いにくいからです。\n次に、【季節風がとどきにくい地域】です。瀬戸内は、夏の季節風を四国山地に、冬の季節風を中国山地にさえぎられるので、一年を通して降水量が少なく、ため池がつくられてきました。中央高地は、周りを高い山に囲まれ海から遠いので降水量が少なく、夏と冬、昼と夜の気温差が大きくなります。\n【地形】も産業を決めます。山のふもとの【扇状地】は水はけがよいので、果樹園に利用されます(甲府盆地のぶどう・もも)。水はけのよすぎる【台地】は畑や茶畑に(牧ノ原の茶、シラス台地の畑作)、川の下流の平野は水田に、という関係は全国で共通です。\n工業も、つながりで整理できます。原料や燃料の多くを輸入にたよる日本では、鉄鋼や石油化学などの工業は【臨海部】に集まり、太平洋ベルトができました。一方、小さくて軽く高価な IC(集積回路)などの電子部品は、トラックや飛行機で運んでも利益が出るので、【高速道路や空港の近く】の内陸にも工場が広がりました。九州や東北に半導体関連の工場が多いのは、その例です。',
        key: '季節風(冬:日本海側に雪、夏:太平洋側に雨)と山地のさえぎりで気候が決まる。扇状地=果樹、台地=畑・茶、平野=水田。重い原料の工業は臨海部、軽い IC は空港・高速道路の近く。' },
      { h: '入試ではこう出る:雨温図と統計の判定', t: '高校入試の日本地理では、①【雨温図】からどの都市かを判断する問題、②【統計表】(農産物の生産量・産業別の割合など)から都道府県を当てる問題、③地図や資料をもとに理由を説明する記述問題がよく出ます。\n①の雨温図は、【気温】と【降水量】の2つの特徴で判断します。冬の気温が0℃を大きく下回る→北海道。冬の降水量が多い→日本海側(上越・金沢など)。一年中降水量が少ない→瀬戸内(高松・岡山など)か中央高地(松本など)で、冬に0℃前後まで冷えこむなら中央高地。夏の降水量が多く冬は乾燥→太平洋側(東京・高知など)。一年中温暖で降水量が多い→南西諸島(那覇)です。\n②の統計問題では、【1位の品目】だけでなく、組み合わせで判断します。たとえば「農業産出額にしめる畜産の割合が大きい」は北海道・鹿児島・宮崎、「米の割合が大きい」は新潟・秋田などの北陸・東北、「果実の割合が大きい」は和歌山・山梨・青森などです。\n③の記述では、「気候や地形の特徴(原因)→だから〜がさかん(結果)」の形で書きます。「〜だから。」と理由の文末で終えることも忘れないようにしましょう。\n時間配分のコツとして、雨温図や統計の問題は、まず確実に分かる特徴(冬の雪、極端な数値)から候補をしぼり、残りを消去法で決めると速く解けます。',
        key: '雨温図:冬の降水多=日本海側、一年中少雨=瀬戸内・中央高地(冬に冷えこむのは中央高地)、冬0℃を大きく下回る=北海道。統計は組み合わせで判断。',
        ex: [
          { q: '次の A〜C の雨温図の特徴にあてはまる都市を、下のア〜ウから選びなさい。\nA 一年を通して降水量が少なく、冬の気温は5℃前後で、それほど冷えこまない。\nB 冬(12〜2月)の降水量が多く、夏よりも冬のほうが降水量が多い月がある。\nC 一年を通して降水量が少なく、冬の平均気温は0℃前後まで下がり、夏と冬の気温差が大きい。\nア 松本市(長野県) イ 高松市(香川県) ウ 上越市(新潟県)', hint: '「少雨」の地域は瀬戸内と中央高地の2つ。冬の冷えこみで区別します。', steps: ['B は冬の降水量が多いので、北西の季節風で雪が多い日本海側。上越市(ウ)。', 'A と C はどちらも一年中少雨なので、瀬戸内か中央高地。', 'C は冬に0℃前後まで冷えこみ、気温差が大きいので、内陸で標高の高い中央高地の松本市(ア)。', 'A は冬もそれほど冷えこまないので、瀬戸内の高松市(イ)。'], a: 'A イ B ウ C ア', check: '高松は海に近く冬も比較的温暖、松本は内陸の盆地で冬に冷えこむ、という「海からの距離」のちがいで、A と C の区別が説明できるかを確かめます。' },
          { q: '次の(1)〜(3)の特徴にあてはまる県を答えなさい。\n(1) 農業産出額のうち畜産の割合が半分をこえ、さつまいもの生産量が全国1位で、茶の生産もさかんである。\n(2) 米の農業産出額が多く、冬は雪が多い。金属洋食器の地場産業で知られる燕市がある。\n(3) りんごの生産量が全国1位で、県の西部に世界自然遺産の白神山地がある。', hint: '(1) はシラス台地、(2) は北陸の水田単作、(3) は東北の果樹を思い出します。', steps: ['(1) シラス台地が広がり、稲作に向かないため畜産やさつまいも・茶などの畑作がさかん。鹿児島県。', '(2) 冬の雪で裏作がしにくく水田単作が中心で、米どころとして知られる。燕市の金属洋食器は、冬の副業から発展した地場産業。新潟県。', '(3) りんごの生産量1位は青森県。白神山地は青森県と秋田県にまたがる。', '3つとも、自然条件と産業を結びつけて判断できることを確かめる。'], a: '(1) 鹿児島県 (2) 新潟県 (3) 青森県', check: '(1) で宮崎県と迷ったら、さつまいもの生産量1位が鹿児島県であることで決めます。(3) で秋田県と迷ったら、りんごで青森県に決めます。' }
        ] }
    ],
    faq: [
      ['テーマ(中心となる考え方)は、教科書と同じでないといけないの?', '教科書の出版社によって、地方とテーマの組み合わせは少しちがいます。テストでは、自分の教科書のテーマを確認しておきましょう。\n大切なのは、テーマそのものを覚えることよりも、「テーマから理由をつけて特色を説明できる」ことです。どのテーマでも、その考え方は同じです。'],
      ['生産量の順位は、どこまで覚えればいいの?', 'りんご(青森県)、さくらんぼ(山形県)、ぶどう・もも(山梨県)、乳牛(北海道)のように、長い間1位が変わらない代表的なものから覚えましょう。\n順位は年によって入れかわることがあるので、細かい数字よりも「なぜその地域でさかんなのか」という理由とセットで覚えるほうが入試に強くなります。'],
      ['促成栽培と抑制栽培は、どう見分ければいいの?', 'どちらも「ほかの産地と出荷時期をずらして高く売る」という目的は同じです。\n温暖な気候で時期を「早める」のが促成栽培(宮崎平野・高知平野)、すずしい気候で時期を「おくらせる」のが抑制栽培(高原野菜)です。気候が暖かいかすずしいかで見分けましょう。'],
      ['同じ「降水量が少ない」でも、瀬戸内と中央高地では理由がちがうの?', 'ちがいます。瀬戸内は、夏の南東の季節風を四国山地に、冬の北西の季節風を中国山地にさえぎられるので、一年を通して雨や雪が少なくなります。\n中央高地は、周りを高い山に囲まれ、海から遠い内陸にあるので、湿った風がとどきにくくなります。内陸なので、夏と冬、昼と夜の気温差が大きいのも特徴です。どちらも「山にさえぎられる」点は共通ですが、海に近いかどうかで、冬の気温に差が出ます。']
    ],
    drill: [
      { lv: 1, q: '火山の噴出物が積もってできた台地で、鹿児島県や宮崎県に広がるものを何といいますか。', a: 'シラス台地', exp: 'シラス台地は、火山の噴出物(シラス)が厚く積もってできた台地です。水はけがよすぎて水田に向かないため、さつまいもや茶などの畑作や、豚・肉用牛などの畜産がさかんです。\n九州地方のテーマ「火山と人々のくらし」と結びつけて覚えましょう。' },
      { lv: 1, q: '本州四国連絡橋のうち、瀬戸大橋が結んでいる2つの県を答えなさい。', a: '岡山県と香川県', exp: '本州四国連絡橋には、①神戸・鳴門ルート(兵庫県—徳島県、明石海峡大橋・大鳴門橋)、②児島・坂出ルート(岡山県—香川県、瀬戸大橋)、③尾道・今治ルート(広島県—愛媛県、しまなみ海道)の3つがあります。\n瀬戸大橋は児島・坂出ルートにあり、道路と鉄道の両方が通っているのが特徴です。' },
      { lv: 1, q: '愛知県を中心に広がり、製造品出荷額が全国一の工業地帯を何といいますか。また、その中心となる工業を答えなさい。', a: '中京工業地帯・自動車工業(輸送機械工業)', exp: '中京工業地帯は、愛知県・三重県を中心に広がる工業地帯で、製造品出荷額は全国の工業地帯・地域の中で最も多くなっています。\n豊田市を中心とする自動車工業がとくにさかんで、関連する部品工場も周りに集まっています。' },
      { lv: 2, q: '山梨県の甲府盆地で、ぶどうやももの栽培がさかんな理由を、地形と気候にふれて説明しなさい。', a: '盆地のふちに水はけのよい扇状地が広がっていて果樹の栽培に適しているうえ、降水量が少なく、夏の昼と夜の気温差が大きい気候も果物の栽培に向いているから。', exp: '扇状地は、川が山から平地に出るところに土砂が積もってできた、ゆるやかな傾きの地形です。つぶの大きい砂や石が多いので水はけがよく、水田には向きませんが、果樹の栽培に適しています。\n盆地は降水量が少なく、昼と夜の気温差が大きいので、果物が甘く育ちやすいといわれます。地形と気候の両方を書くことが採点のポイントです。' },
      { lv: 2, q: '北海道の十勝平野などで行われている「輪作」とはどのような農業か、その目的とともに説明しなさい。', a: '同じ畑で、年ごとにちがう種類の作物を順番に栽培する農業。同じ作物を続けてつくることで土の栄養がかたよったり病気が出やすくなったりするのを防ぎ、地力を保つため。', exp: '十勝平野では、小麦・てんさい・じゃがいも・豆類などを、年ごとに畑を変えて順番に栽培しています。\n同じ作物を同じ畑で続けてつくると、作物の育ちが悪くなる連作障害が起こりやすくなります。輪作はそれを防ぎ、土の力(地力)を保つための工夫です。' },
      { lv: 2, q: '中国・四国地方の山間部で問題になっている「過疎」とはどのような状態ですか。また、地域を活性化させる取り組みの例を1つ答えなさい。', a: '過疎:人口が大きく減り、地域の社会生活(交通・医療・学校など)を維持するのが難しくなった状態。取り組みの例:徳島県上勝町で、料理にそえる葉や花を「つまもの」として出荷し、高齢者の仕事と収入を生み出している。', exp: '山間部では、若い人が仕事を求めて都市に移り、高齢化と人口減少が進んでいます。その結果、バスの路線がなくなる、学校や病院が閉じるなど、くらしを支えるしくみを保つのが難しくなります。\n対策として、地域の資源を生かした特産品づくり(町おこし・村おこし)や、農産物を加工・販売まで行う6次産業化、移住者の受け入れなどが行われています。具体例を1つ挙げられれば得点できます。' },
      { lv: 3, q: '冬に日本海側で雪が多くなるしくみを、「季節風」「日本海」「山地」の3つの語を使って説明しなさい。', a: '冬にユーラシア大陸からふく冷たく乾いた北西の季節風が、日本海の上を通るときに水蒸気をふくんで湿った風になり、日本列島の山地にぶつかって上昇し、日本海側に多くの雪を降らせるから。', exp: '大陸からの季節風は、はじめは冷たく乾いています。日本海を流れる暖流(対馬海流)の上を通るときに、海から水蒸気をたっぷりふくみます。\nその風が日本列島の中央の山地にぶつかって上昇すると、雲ができて日本海側に雪を降らせます。山をこえて太平洋側に下りるときには水蒸気を失っているので、太平洋側は乾燥した晴れの日が多くなります。\n採点のポイントは、①季節風が水蒸気をふくむ場所(日本海)、②山地にぶつかること、③雪が降るのは日本海側であること、の3点がつながっているかです。' },
      { lv: 3, q: '東京への一極集中によって起きている問題を2つ挙げ、その対策の例を1つ説明しなさい。', a: '問題:朝夕の通勤ラッシュや交通渋滞が起きる。地価や住宅費が高くなる。(ほかに、ごみの増加、災害時に首都の機能がまひするおそれ など)対策の例:さいたま新都心や幕張新都心、横浜みなとみらい21などに、オフィスや国の機関の一部を移して、都心の機能を分散させる。', exp: '東京には、国の政治の中心や大企業の本社、大学などが集まり、人口と機能が集中しています。その結果、過密による通勤ラッシュ・渋滞・地価の上昇・ごみ問題などが起きています。\nまた、首都の機能が東京に集中していると、大きな地震などの災害が起きたときに、国全体への影響が大きくなるおそれもあります。\n対策としては、都心の機能を周辺の新都心に分散させる取り組みや、国の機関の地方への移転などがあります。採点のポイントは、問題点と対策が対応しているかです。' }
    ],
    terms: [['カルデラ', '火山の噴火によってできた大きなくぼ地。阿蘇山のものが有名'], ['シラス台地', '九州南部に広がる、火山の噴出物が積もった台地。水はけがよく稲作に向かない'], ['ストロー現象', '交通網の整備によって、人や物が大都市に吸い寄せられ、地方がおとろえる現象'], ['過疎', '人口が大きく減り、地域の生活を維持するのがむずかしくなること'], ['地場産業', 'その地域の原料や技術を生かして古くから発達してきた産業'], ['一極集中', '政治・経済などの機能や人口が、1つの都市に集中すること'], ['やませ', '夏に東北地方の太平洋側にふく冷たく湿った北東の風。冷害の原因'], ['客土', 'ほかの土地からよい土を運び入れて、土地を改良すること']],
    miss: ['促成栽培と抑制栽培を逆に覚える。どちらも「時期をずらす」なので混ざりやすいからです。「暖かい=早める=促成」「すずしい=おくらせる=抑制」と気候とセットで覚えましょう。', '瀬戸内地方は海に近いから雨が多い、と考えてしまう。実際は中国山地と四国山地が季節風をさえぎるので雨が少なく、ため池が多いのです。地図で山地の位置を確かめましょう。', '昼間人口と夜間人口の多い・少ないを逆にする。「昼に人が集まる所(都心)は昼間人口が多い」と、場面を思いうかべて考えましょう。', '産物や工業地帯の名前だけを覚え、理由を書けない。記述問題では「自然条件や交通などの理由 → 産業」の形が求められるので、テーマから理由をつなげて覚えましょう。'],
    sum: ['7地方をそれぞれ「中心となる考え方」で整理し、テーマ → 原因 → 結果とつなげる。', '九州は火山と温暖な気候、中国・四国は交通による結びつきと過疎、近畿は歴史的景観と環境保全。', '中部は東海・中央高地・北陸で産業が大きくちがう。', '関東は人口と機能が東京に集中し、都心は昼間人口が多い。', '東北はやませ・冷害と伝統文化、北海道は開拓の歴史と自然を生かした大規模な農業。'],
    next: '次は「身近な地域の調査」(c_chizu)で、地形図の読み取りを練習しましょう。高校では「地理総合」で、日本の地域の特色を世界と比べながら学びます。'
  };

  // ===== 中学社会:人権と日本国憲法 =====
  L.c_jinken = {
    goal: '日本国憲法の三大原則と、基本的人権の種類(平等権・自由権・社会権・参政権・請求権・新しい人権)を、具体例と結びつけて説明できるようになる。公共の福祉による人権の制限の意味も説明できるようになる。',
    intro: 'スポーツの試合にルールブックがあるように、国にもいちばん大切なルールブックがあります。それが【憲法】です。ただし憲法は、国民をしばるためのものではありません。国の力が強くなりすぎて、人々の自由や生活がおびやかされないように、【国の権力をしばる】ためのルールです。この単元では、日本国憲法がどんな考え方でつくられ、私たちのどんな権利を守っているのかを学びます。',
    pre: '【人権(基本的人権)】とは、人間が生まれながらにしてもっている、人間らしく生きるための権利です。だれかからあたえられるものではなく、すべての人が等しくもっています。\n【憲法】は国の最高法規で、法律や命令は憲法に反してはなりません。憲法によって国の権力を制限し、人権を守るという考え方を【立憲主義】といいます。\n日本には、日本国憲法の前に【大日本帝国憲法】(1889年発布)がありました。この憲法では主権は天皇にあり、国民は「臣民」とされ、権利は「法律の範囲内」でしか認められませんでした。\n第二次世界大戦に敗れた後、日本は民主化を進め、新しい憲法をつくりました。これが日本国憲法です。\n政治のしくみ(国会・内閣・裁判所の三権分立)は別の単元でくわしく学びますが、この単元では、そのもとになる憲法の考え方を中心に学びます。',
    secs: [
      { h: '人権の歴史', t: '今では当たり前の人権も、人々が長い時間をかけて、国王や政府と争いながら獲得してきたものです。\n17〜18世紀のヨーロッパでは、国王が強い権力をもつ絶対王政が行われていました。これに対して、ロックやモンテスキュー、ルソーなどの思想家が、人は生まれながらに自由・平等であること、権力を分けるべきことなどを説きました。\nイギリスでは【権利章典】(1689年)で議会の権利が確認され、アメリカでは【独立宣言】(1776年)、フランスでは【人権宣言】(1789年)が出されました。このころに確立した人権は、主に国から干渉されない【自由権】でした。\nしかし19世紀になって資本主義が発達すると、貧富の差が広がり、自由だけでは人間らしい生活ができない人が増えました。そこで20世紀には、国が人々の生活を支える【社会権】が考えられるようになり、ドイツの【ワイマール憲法】(1919年)で初めて保障されました。\n第二次世界大戦後には、国際連合で【世界人権宣言】(1948年)が採択され、人権は世界共通の目標になりました。',
        key: '人権は「自由権(18世紀)→ 社会権(20世紀、ワイマール憲法)→ 国際的な保障」と広がってきた。',
        chain: { title: '人権の広がり', items: [
          ['背景', '絶対王政のもとで、国王が強い権力をふるう', '思想家が自由・平等や権力の分立を説く'],
          ['できごと', '権利章典(1689年)・アメリカ独立宣言(1776年)・フランス人権宣言(1789年)', '国から干渉されない自由権が確立'],
          ['結果', '資本主義の発達で貧富の差が拡大', 'ワイマール憲法(1919年)で社会権が初めて保障される'],
          ['その後', '世界人権宣言(1948年)', '人権の保障が世界共通の目標に']] } },
      { h: '日本国憲法の成り立ちと三大原則', t: '日本国憲法は、【1946年11月3日に公布】され、【1947年5月3日に施行】されました。現在、11月3日は文化の日、5月3日は憲法記念日になっています。\n日本国憲法には、3つの基本原則があります。【国民主権】・【基本的人権の尊重】・【平和主義】です。\n【国民主権】とは、国の政治のあり方を最終的に決める力(主権)が国民にあるということです。国民は、選挙で選んだ代表者を通じて政治を行います。\n天皇は、日本国と日本国民統合の【象徴】とされ、政治についての権限をもちません。天皇は、内閣の助言と承認にもとづいて、法律の公布や国会の召集などの【国事行為】だけを行います。\n憲法は国の最高法規なので、簡単に変えられないように、ふつうの法律よりきびしい改正の手続きが定められています(第96条)。まず、衆議院と参議院の【それぞれの総議員の3分の2以上】の賛成で国会が改正を【発議】します。次に【国民投票】を行い、【有効投票の過半数】の賛成が得られれば改正が決まり、天皇が国民の名で公布します。',
        key: '三大原則は国民主権・基本的人権の尊重・平和主義。天皇は象徴で国事行為のみ。改正は各院の総議員の3分の2以上で発議 → 国民投票で過半数。',
        ex: [{ q: '日本国憲法を改正するための手続きを、順を追って説明しなさい。また、ふつうの法律よりきびしい手続きになっている理由を答えなさい。', hint: '国会での発議と、国民投票の2段階があります。', steps: ['衆議院と参議院のそれぞれで、総議員の3分の2以上の賛成を得て、国会が改正案を国民に発議する。', '国民投票を行い、有効投票の過半数の賛成が得られると、改正が決まる。', '改正が決まると、天皇が国民の名で公布する。', '理由:憲法は国の最高法規で、国の権力をしばり人権を守るためのルールなので、その時々の多数派が簡単に変えられないようにしている。'], a: '各議院の総議員の3分の2以上の賛成で国会が発議 → 国民投票で過半数の賛成 → 天皇が国民の名で公布。理由は、最高法規である憲法を、一時的な多数の意見で簡単に変えられないようにするため。', check: '「出席議員」ではなく「総議員」の3分の2であること、最後に必ず国民投票があることを確かめます。' }] },
      { h: '平和主義', t: '日本は、第二次世界大戦で多くの犠牲を出し、他国にも大きな被害をあたえました。その反省から、日本国憲法は【平和主義】を原則としています。\n憲法の【前文】では、恒久の平和を願い、全世界の国民が平和のうちに生存する権利をもつことを確認しています。\n【第9条】では、①国際紛争を解決する手段としての【戦争を放棄】すること、②そのための【戦力をもたない】こと、③国の【交戦権を認めない】こと、を定めています。\n日本には、国を防衛するための【自衛隊】があります。政府は、自衛隊は自衛のための必要最小限度の実力であり、憲法が禁じる「戦力」にはあたらないという立場をとっています。ただし、自衛隊と第9条の関係については、さまざまな意見があります。\nまた日本は、アメリカと【日米安全保障条約】を結び、国内にアメリカ軍の基地があります。核兵器については、「【持たず、つくらず、持ちこませず】」という【非核三原則】をかかげています。唯一の戦争被爆国として、核兵器の廃絶を世界にうったえる役割も期待されています。',
        key: '第9条は戦争の放棄・戦力の不保持・交戦権の否認。非核三原則は「持たず、つくらず、持ちこませず」。' },
      { h: '基本的人権の全体像と平等権', t: '日本国憲法は、基本的人権を「侵すことのできない永久の権利」として保障しています。その土台にあるのが、【個人の尊重】(第13条)です。一人ひとりをかけがえのない個人として大切にするという考え方です。\n基本的人権は、大きく次のように分けられます。【平等権】、【自由権】、【社会権】、そして人権を守るための権利である【参政権】と【請求権】です。さらに、社会の変化にともなって主張されるようになった【新しい人権】もあります。\n【平等権】は、すべての国民が【法の下に平等】であり、人種・信条・性別・社会的身分などによって差別されないという権利です(第14条)。\nしかし現実には、今も差別が残っています。部落差別、アイヌの人々への差別、在日韓国・朝鮮人への差別、女性への差別、障がいのある人への差別などです。\nこれらをなくすために、さまざまな法律がつくられてきました。男女が職場で平等にあつかわれることをめざす【男女雇用機会均等法】(1985年)、男女が対等に社会に参画することをめざす【男女共同参画社会基本法】(1999年)、アイヌの人々を先住民族と明記した【アイヌ施策推進法】(2019年)などです。障がいのある人もない人も共にくらせるよう、段差をなくすなどの【バリアフリー】も進められています。',
        key: '人権の土台は個人の尊重。平等権は法の下の平等(第14条)。差別をなくすための法律や取り組みがある。',
        flow: { title: '基本的人権の分類', cols: 4, head: ['平等権', '自由権', '社会権', '人権を守る権利'],
          rows: [
            [['個人の尊重(第13条)', 'k', 4, 'すべての人権の土台']],
            [['法の下の平等', 'b', 1, '第14条'], ['精神の自由', 'r', 1, '思想・信教・表現'], ['生存権', 'g', 1, '第25条'], ['参政権', 'o', 1, '選挙権・被選挙権など']],
            [['男女の平等', 'b', 1, '男女雇用機会均等法'], ['身体の自由', 'r', 1, '令状なしに逮捕されない'], ['教育を受ける権利', 'g', 1, '勤労の権利'], ['請求権', 'o', 1, '裁判を受ける権利など']],
            [['差別の解消', 'b', 1, 'バリアフリーなど'], ['経済活動の自由', 'r', 1, '職業選択・財産権'], ['労働基本権', 'g', 1, '団結権など'], ['新しい人権', 'gr', 1, '環境権・知る権利など']]
          ],
          legend: [['b', '平等権'], ['r', '自由権'], ['g', '社会権'], ['o', '参政権・請求権'], ['gr', '新しい人権']] } },
      { h: '自由権', t: '【自由権】は、国から不当に干渉されず、自由に考え、行動できる権利です。人権の中で最も早く確立した権利で、大きく3つに分けられます。\n①【精神の自由】:思想・良心の自由、信教の自由、集会・結社・表現の自由、学問の自由など。心の中で何を考え、何を信じ、どう表現するかを国に強制されない自由です。\n②【身体の自由】:正当な理由なく体を拘束されない自由です。奴隷的拘束や苦役からの自由、法律の定める手続きによらなければ刑罰を科されないこと、裁判官の出す【令状】がなければ逮捕されないこと(現行犯を除く)、拷問の禁止、自分に不利なことを話さなくてよい【黙秘権】などが定められています。大日本帝国憲法のもとで不当な逮捕や拷問があった反省から、くわしく定められています。\n③【経済活動の自由】:住む場所や職業を自由に選ぶ【居住・移転・職業選択の自由】と、自分の財産をもつ【財産権】です。\nなぜ自由権が大切なのでしょうか。国が人々の考えや行動を勝手に制限できるようになると、政府を批判する意見が言えなくなり、民主主義そのものが成り立たなくなってしまうからです。',
        key: '自由権は精神の自由・身体の自由・経済活動の自由の3つ。国から干渉されない権利。',
        ex: [{ q: '次の権利は、自由権の「精神の自由」「身体の自由」「経済活動の自由」のどれにあたるか。(1) 自分の好きな宗教を信じる。(2) 自分の就きたい職業を選ぶ。(3) 令状がなければ逮捕されない。(4) 自分の意見を本にして出版する。', hint: '心の中・からだ・お金や仕事、のどれに関わるかで分けます。', steps: ['(1) 宗教を信じることは心の中の自由なので、信教の自由で精神の自由。', '(2) 職業を選ぶことは仕事や生活の自由なので、職業選択の自由で経済活動の自由。', '(3) 不当に体を拘束されないことなので、身体の自由。', '(4) 意見を出版することは表現の自由なので、精神の自由。'], a: '(1) 精神の自由 (2) 経済活動の自由 (3) 身体の自由 (4) 精神の自由', check: '「心=精神」「からだ=身体」「仕事・財産=経済活動」と分類の基準を言いかえて確かめます。' }] },
      { h: '社会権と、人権を守るための権利', t: '【社会権】は、人間らしい生活を送るために、国に対して積極的な支えを求める権利です。自由権が「国は口を出さないで」という権利なら、社会権は「国は手を差しのべて」という権利です。\n社会権の中心は、第25条の【生存権】です。「すべて国民は、健康で文化的な最低限度の生活を営む権利を有する」と定められ、これにもとづいて、生活保護などの【社会保障制度】が整えられています。\nほかに、【教育を受ける権利】、【勤労の権利】、そして働く人が団結して労働組合をつくる【団結権】、使用者と交渉する【団体交渉権】、ストライキなどを行う【団体行動権】の【労働基本権】(労働三権)があります。\n人権を守るための権利も大切です。【参政権】は政治に参加する権利で、【選挙権】(18歳以上)、選挙に立候補する【被選挙権】、最高裁判所の裁判官の【国民審査】、憲法改正の【国民投票】などがあります。\n【請求権】は、人権が侵されたときに国に救済を求める権利で、【裁判を受ける権利】、公務員の不法な行為で損害を受けたときの【国家賠償請求権】、無罪になった人が補償を求める【刑事補償請求権】などがあります。\nまた憲法は、国民の義務として、【子どもに普通教育を受けさせる義務】、【勤労の義務】、【納税の義務】の3つを定めています。',
        key: '社会権は国に支えを求める権利(生存権・教育・勤労・労働基本権)。参政権・請求権は人権を守る権利。国民の三大義務も合わせて覚える。',
        ex: [{ q: '次の例は、自由権・社会権・参政権・請求権のどれに関係するか。(1) 失業して収入がなくなった人が、生活保護を受ける。(2) 18歳になって、衆議院議員の選挙で投票する。(3) 無実の罪で長く拘束された人が、無罪の判決を受けた後、国に補償を求める。(4) 労働者が労働組合をつくり、賃金について会社と話し合う。', hint: '「国に支えてもらう」「政治に参加する」「国に救済を求める」のどれにあたるかを考えます。', steps: ['(1) 生活保護は、生存権にもとづいて国が生活を支える制度なので、社会権。', '(2) 選挙で投票するのは政治に参加することなので、参政権。', '(3) 不当な拘束について国に補償を求めるのは刑事補償請求権なので、請求権。', '(4) 労働組合をつくり会社と交渉するのは団結権・団体交渉権なので、社会権(労働基本権)。'], a: '(1) 社会権 (2) 参政権 (3) 請求権 (4) 社会権', check: '(4) の労働基本権が自由権ではなく社会権に入ることを確かめます。働く人の生活を守るための権利だからです。' }] },
      { h: '新しい人権と公共の福祉', t: '社会が大きく変化すると、憲法をつくったときには想定されていなかった問題が生まれます。そこで、主に第13条の幸福追求権や第25条の生存権などをもとにして、【新しい人権】が主張されるようになりました。\n【環境権】:よい環境の中で生活する権利です。高度経済成長期の公害がきっかけで主張されました。日当たりを確保する【日照権】もその一つで、大規模な開発の前に環境への影響を調べる【環境アセスメント】も行われています。\n【知る権利】:国や地方公共団体がもつ情報を知る権利です。民主主義では、国民が正しい情報をもとに判断することが大切だからです。これにもとづいて【情報公開制度】が整えられました。\n【プライバシーの権利】:私生活や個人の情報をみだりに公開されない権利です。情報化の進展とともに重要になり、【個人情報保護制度】が整えられています。\n【自己決定権】:自分の生き方や生活を自分で決める権利です。医療で、医師から十分な説明を受けたうえで治療方法を選ぶ【インフォームド・コンセント】や、臓器提供の意思を示すカードなどがその例です。\n人権は最大限に尊重されますが、ほかの人の人権とぶつかることもあります。そこで憲法は、人権は【公共の福祉】のために利用する責任があると定めています。公共の福祉とは、社会全体の利益、つまり人々の人権どうしがぶつかったときに調整するための考え方です。たとえば、表現の自由があっても他人の名誉を傷つけることは許されず、道路などの建設のためには、正当な補償のもとで土地を提供してもらう(財産権の制限)ことがあります。',
        key: '新しい人権は環境権・知る権利・プライバシーの権利・自己決定権。人権どうしの衝突は「公共の福祉」で調整される。',
        ex: [{ q: '雑誌に、ある有名人の住所や家族のようすを本人の許可なくのせることについて、ぶつかり合っている2つの権利を答え、どのように考えればよいか説明しなさい。', hint: '出版する側と、のせられる側、それぞれの権利を考えます。', steps: ['雑誌を出す側には、表現の自由(精神の自由)がある。', 'のせられる有名人には、私生活をみだりに公開されないプライバシーの権利がある。', '2つの人権がぶつかっているので、公共の福祉の考え方で調整する必要がある。', '住所や家族のようすのような私生活の情報は、社会全体が知る必要が小さく、のせられた人の被害が大きいので、プライバシーの権利を重く見る考え方が強い。'], a: '表現の自由とプライバシーの権利がぶつかっている。人権どうしの衝突は公共の福祉の考え方で調整し、社会全体が知る必要性が小さい私生活の情報は、本人のプライバシーを守ることが重視される。', check: 'どちらか一方だけが正しいと決めつけず、「2つの人権の調整」として説明できているかを確かめます。' }] },
      { h: 'もっと深く:立憲主義──憲法はだれをしばるのか', t: '「法律」は国民が守るきまり、と考える人が多いでしょう。では、「憲法」はだれが守るきまりなのでしょうか。答えのカギになるのが【立憲主義】という考え方です。\n立憲主義とは、【憲法によって国家の権力を制限し、国民の人権を守る】という考え方です。歴史の中で、王や政府が権力を使って人々の自由をうばうことがくり返されてきました。そこで、権力をもつ側に「これ以上はしてはいけない」という歯止めをかけるために、憲法がつくられてきたのです。\n日本国憲法も、この考え方に立っています。第99条は、憲法を尊重し守る義務を負う人として、【天皇・摂政・国務大臣・国会議員・裁判官その他の公務員】を挙げています。国民ではなく、権力を使う立場の人々が名指しされている点に、立憲主義の考え方が表れています。(国民の義務としては、別に、普通教育を受けさせる義務・勤労の義務・納税の義務が定められています。)\n憲法は国の【最高法規】(第98条)で、憲法に反する法律や命令は効力をもちません。それを確かめるしくみが、裁判所の【違憲審査権】(第81条)です。具体的な裁判を通して、法律などが憲法に違反していないかを判断し、最終的な決定権をもつ最高裁判所は【憲法の番人】とよばれます。\nこの考え方は、【法の支配】とも結びついています。権力者が思いのままに人を支配する「人の支配」ではなく、国民の代表がつくった法によって権力者もしばられる、という原則です。人権の単元と、国会・内閣・裁判所の単元は、この考え方でつながっているのです。',
        key: '立憲主義=憲法で国家権力を制限し、人権を守る。憲法尊重擁護義務(第99条)を負うのは天皇・国務大臣・国会議員・裁判官などの公務員。違憲審査権の最終判断は最高裁(憲法の番人)。' },
      { h: '入試ではこう出る:条文・事例・公共の福祉', t: '高校入試の人権の単元では、①【条文の空らん補充】、②【事例がどの権利にあたるか】を答える問題、③【公共の福祉による制限】や新しい人権について説明する記述問題がよく出ます。\n①の条文問題では、よく出る条文のキーワードを正確に覚えておくことが大切です。第13条「個人として尊重される」「幸福追求」、第14条「法の下に平等」、第25条「健康で文化的な最低限度の生活」は、特によく出ます。\n②の事例問題では、「国に何かをしないでほしい」なら自由権、「国に何かをしてほしい」なら社会権、「政治に参加する」なら参政権、「国に救済を求める」なら請求権、と【国との向き合い方】で分けると判断しやすくなります。\n③の公共の福祉の問題では、どの人権が、どんな理由で制限されているのかを答えます。とくに【経済活動の自由】は、ほかの人のくらしや社会全体に影響が大きいため、精神の自由より広く制限されやすいとされています。資格が必要な職業(医師・弁護士など)や、道路建設のための土地の収用(正当な補償が必要)などが例です。\n新しい人権は、憲法に直接の規定がないため、第13条の【幸福追求権】や第25条の生存権などを根拠にして主張されてきた、という点もあわせて答えられるようにしておきましょう。',
        key: 'よく出る条文=第13条(個人の尊重・幸福追求)、第14条(法の下の平等)、第25条(生存権)。事例は「国との向き合い方」で分類。経済活動の自由は公共の福祉で制限されやすい。',
        ex: [
          { q: '次の日本国憲法の条文の( ① )〜( ③ )にあてはまる語句を答えなさい。\n第13条 すべて国民は、( ① )として尊重される。生命、自由及び幸福追求に対する国民の権利については、( ② )に反しない限り、立法その他の国政の上で、最大の尊重を必要とする。\n第25条 すべて国民は、健康で( ③ )な最低限度の生活を営む権利を有する。', hint: '第13条は人権全体の土台となる条文、第25条は社会権の中心となる生存権の条文です。', steps: ['第13条の初めは、人権の土台となる「個人の尊重」を定めている。①は「個人」。', '人権も無制限ではなく、ほかの人の人権との調整が必要。②は「公共の福祉」。', '第25条は生存権の規定で、「健康で文化的な最低限度の生活」。③は「文化的」。', '第13条の「幸福追求に対する国民の権利」は、新しい人権の根拠にもなっていることを確認する。'], a: '① 個人 ② 公共の福祉 ③ 文化的', check: '第13条が「新しい人権」の根拠、第25条が「社会権(生存権)」の根拠になることと結びつけて覚えているかを確かめます。' },
          { q: '次のア〜エのうち、公共の福祉によって「経済活動の自由」が制限されている例をすべて選びなさい。\nア 医師として働くには、国家試験に合格して免許を得なければならない。\nイ 他人の名誉を傷つける内容を出版すると、罰せられることがある。\nウ 道路を広げるために、正当な補償のうえで、土地を国や自治体に提供させることがある。\nエ 大規模なデモ行進を行うには、事前に届け出が必要な場合がある。', hint: 'それぞれ、どの自由が制限されているのかを「精神の自由」「経済活動の自由」に分けて考えます。', steps: ['ア:医師の資格がなければその職業につけないので、職業選択の自由(経済活動の自由)の制限。', 'イ:出版の内容が制限されているので、表現の自由(精神の自由)の制限。', 'ウ:自分の土地を提供させられるので、財産権(経済活動の自由)の制限。憲法第29条で、正当な補償が必要とされている。', 'エ:デモ行進は集会や表現の自由(精神の自由)にあたる。'], a: 'ア、ウ', check: 'ア・ウはどちらも「仕事」や「財産」にかかわる自由で、ほかの人の安全や社会全体の利益のために制限されている点が共通していることを確かめます。' }
        ] }
    ],
    faq: [
      ['自由権と社会権は、どう見分ければいいの?', '国に対して何を求めているかで見分けます。自由権は「国は干渉しないで」(国家からの自由)、社会権は「国は生活を支えて」(国家による自由)と求める権利です。\nたとえば、職業を自由に選べるのは自由権、働く機会を得られるように国が支えるのは社会権(勤労の権利)です。'],
      ['公共の福祉があると、国はいつでも人権を制限できるの?', 'そうではありません。公共の福祉は、人権どうしがぶつかったときに調整するための考え方で、国の都合で自由に人権をうばうためのものではありません。\n特に、心の中の自由(思想・良心の自由など)はできる限り制限されるべきではないと考えられています。制限が許されるかどうかは、最終的には裁判所が判断します。'],
      ['新しい人権は、憲法に書いてないのに認められるの?', '憲法に直接の言葉はありませんが、第13条の幸福追求権や第25条の生存権、第21条の表現の自由などをもとにして主張されています。\n法律や制度(情報公開制度・個人情報保護制度など)をつくることで、具体的に守られるようになってきました。'],
      ['日本に住む外国人にも、人権は保障されるの?', '基本的人権は、人が生まれながらにもっている権利なので、外国人にも保障されるのが原則です。最高裁判所の判例でも、権利の性質上日本国民だけを対象とするものをのぞいて、外国人にも保障されると考えられています。\nその例外の代表が参政権です。現在の法律では、国政選挙だけでなく地方選挙でも、外国人の選挙権は認められていません。']
    ],
    drill: [
      { lv: 1, q: '日本国憲法の三大原則をすべて答えなさい。', a: '国民主権、基本的人権の尊重、平和主義', exp: '日本国憲法は、国の政治のあり方を最終的に決める力が国民にあるという国民主権、人が生まれながらにもつ権利を守る基本的人権の尊重、戦争を放棄する平和主義の3つを基本原則としています。\n大日本帝国憲法が天皇主権だったこととの対比で問われることも多いので、あわせて確認しておきましょう。' },
      { lv: 1, q: '生存権を定めているのは、日本国憲法の第何条ですか。', a: '第25条', exp: '第25条は「すべて国民は、健康で文化的な最低限度の生活を営む権利を有する」と定めています。社会権の中心となる権利です。\nこの条文にもとづいて、生活保護などの社会保障制度が整えられています。' },
      { lv: 1, q: '日本国憲法が定める国民の三大義務をすべて答えなさい。', a: '子どもに普通教育を受けさせる義務、勤労の義務、納税の義務', exp: '国民の義務は、①保護する子どもに普通教育を受けさせる義務(第26条)、②勤労の義務(第27条)、③納税の義務(第30条)の3つです。\n「教育を受ける義務」ではなく、「(子どもに)教育を受けさせる義務」であることに注意しましょう。教育を受けることは子どもの権利です。' },
      { lv: 2, q: '1919年に制定され、世界で初めて社会権を規定した憲法とされるのは何ですか。', a: 'ワイマール憲法(ドイツ)', exp: 'ワイマール憲法は、第一次世界大戦後のドイツで制定された憲法で、人間らしい生活を保障する社会権を初めて規定したことで知られています。\n18世紀の人権宣言が自由権を中心としていたのに対し、20世紀になって社会権が加わった、という人権の歴史の流れの中で位置づけて覚えましょう。' },
      { lv: 2, q: '法律などが憲法に違反していないかを最終的に決定する権限をもつことから、「憲法の番人」とよばれる機関はどこですか。', a: '最高裁判所', exp: 'すべての裁判所は、具体的な裁判を通して、法律や命令などが憲法に違反していないかを判断する違憲審査権をもっています。\nその最終的な決定権をもつのが最高裁判所なので、「憲法の番人」とよばれます。立憲主義(憲法で権力をしばる)を支える重要なしくみです。' },
      { lv: 2, q: '「知る権利」を保障するために、国や地方公共団体が整えてきた制度を何といいますか。', a: '情報公開制度', exp: '知る権利は、国民が政治について判断するために、国や地方公共団体がもつ情報を知ることができる権利です。\nこの権利を保障するために、地方公共団体の情報公開条例や、国の情報公開法が定められ、国民の請求によって行政の文書などを公開するしくみが整えられています。' },
      { lv: 3, q: '新しい人権の一つである「自己決定権」とはどのような権利ですか。医療の場面での具体例を1つ挙げて説明しなさい。', a: '自分の生き方や生活のしかたについて、自分で自由に決める権利。例:医師から病気や治療方法について十分な説明を受け、同意したうえで治療を受ける(インフォームド・コンセント)。', exp: '自己決定権は、憲法に直接の規定はありませんが、第13条の幸福追求権などを根拠に主張されている新しい人権です。\n医療の場面では、患者が十分な説明を受けて自分で治療法を選ぶインフォームド・コンセントや、臓器提供の意思を示す意思表示カードなどが例として挙げられます。\n採点のポイントは、①「自分のことを自分で決める権利」という意味、②それに合った具体例、の2点がそろっているかです。' },
      { lv: 3, q: '経済活動の自由が、精神の自由よりも公共の福祉によって広く制限されやすいのはなぜですか。説明しなさい。', a: '経済活動は、ほかの人の生活や安全、社会全体の利益に与える影響が大きく、自由にまかせると経済的に弱い立場の人が不利益を受けることもあるので、それを防ぐために、法律による規制が広く認められているから。', exp: '自由に商売や開発ができると、たとえば危険な商品の販売、資格のない人による医療、環境の破壊、大企業による市場の独占などが起こるおそれがあります。\nそのため、資格制度、建築の規制、独占禁止法など、社会全体の利益や弱い立場の人を守るための制限が設けられています。\n一方、精神の自由(思想・表現など)は民主政治の土台となる権利なので、その制限はより慎重であるべきだと考えられています。採点のポイントは、「ほかの人や社会全体への影響」と「弱い立場の人を守る」という観点が書かれているかです。' }
    ],
    terms: [['立憲主義', '憲法によって国の権力を制限し、人権を守るという考え方'], ['国民主権', '国の政治のあり方を最終的に決める力が国民にあること'], ['象徴', '天皇の地位。日本国と日本国民統合のしるしで、政治の権限はもたない'], ['国事行為', '天皇が内閣の助言と承認にもとづいて行う形式的・儀礼的な行為'], ['生存権', '健康で文化的な最低限度の生活を営む権利(第25条)'], ['労働基本権', '団結権・団体交渉権・団体行動権の3つ(労働三権)'], ['公共の福祉', '社会全体の利益。人権どうしの衝突を調整する考え方'], ['インフォームド・コンセント', '医師から十分な説明を受けたうえで、患者が治療方法を選ぶこと']],
    miss: ['憲法改正の発議の条件を「出席議員の3分の2」とまちがえる。法律の再可決(衆議院の出席議員の3分の2)と混ざるからです。改正の発議は「各議院の総議員の3分の2以上」と覚えましょう。', '労働基本権を自由権に入れてしまう。働く人の生活を守るために国が保障する権利なので社会権です。分類表を見ながら確かめましょう。', '公布日(1946年11月3日)と施行日(1947年5月3日)を逆にする。「公布 → 半年後に施行」の順で、施行日が憲法記念日だと覚えましょう。', '新しい人権と、それを守る制度の組み合わせをまちがえる。「知る権利=情報公開」「プライバシー=個人情報保護」「自己決定権=インフォームド・コンセント」とセットで覚えましょう。', '公共の福祉を「国の利益のためなら何でも制限できる」と誤解する。あくまで人権どうしの調整の考え方であることをおさえましょう。'],
    sum: ['憲法は国の権力をしばり人権を守る最高法規(立憲主義)。', '三大原則は国民主権・基本的人権の尊重・平和主義。天皇は象徴で、国事行為のみを行う。', '改正は各議院の総議員の3分の2以上で発議し、国民投票で過半数の賛成が必要。', '基本的人権は個人の尊重を土台に、平等権・自由権・社会権・参政権・請求権に分けられる。', '環境権・知る権利・プライバシーの権利・自己決定権などの新しい人権がある。', '人権どうしがぶつかるときは、公共の福祉によって調整される。'],
    next: '次は「公民(政治と経済)」(c_m3)で、国会・内閣・裁判所の三権分立と、選挙のしくみを学びましょう。高校では「公共」で、人権と法の考え方をさらに深く学びます。'
  };
})(WPS.LESSONS);

